"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";

type Priority = "low" | "medium" | "high";
type Status = "all" | "open" | "done";
type Theme = "light" | "dark" | "system";

type Task = {
  id: string;
  title: string;
  notes: string;
  priority: Priority;
  dueDate: string;
  done: boolean;
  createdAt: string;
};

type Prefs = {
  theme: Theme;
  status: Status;
  priority: "all" | Priority;
  sort: "newest" | "due" | "priority";
};

const seedTasks: Task[] = [
  {
    id: "seed-1",
    title: "Plan sprint backlog",
    notes: "Review priorities and split large tickets.",
    priority: "high",
    dueDate: new Date().toISOString().slice(0, 10),
    done: false,
    createdAt: new Date().toISOString(),
  },
  {
    id: "seed-2",
    title: "Update project docs",
    notes: "Add setup notes for new contributors.",
    priority: "medium",
    dueDate: "",
    done: true,
    createdAt: new Date(Date.now() - 86400000).toISOString(),
  },
];

const defaultPrefs: Prefs = { theme: "system", status: "all", priority: "all", sort: "newest" };

function useStoredState<T>(key: string, fallback: T) {
  const [value, setValue] = useState<T>(() => {
    if (typeof window === "undefined") return fallback;
    try {
      const raw = localStorage.getItem(key);
      return raw ? (JSON.parse(raw) as T) : fallback;
    } catch {
      return fallback;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // Ignore storage failures.
    }
  }, [key, value]);

  return [value, setValue] as const;
}

function emptyTask(): Task {
  return {
    id: crypto.randomUUID(),
    title: "",
    notes: "",
    priority: "medium",
    dueDate: "",
    done: false,
    createdAt: new Date().toISOString(),
  };
}

export default function Page() {
  const [tasks, setTasks] = useStoredState<Task[]>("task-manager.tasks", seedTasks);
  const [prefs, setPrefs] = useStoredState<Prefs>("task-manager.prefs", defaultPrefs);
  const [query, setQuery] = useState("");
  const [editing, setEditing] = useState<Task | null>(null);
  const [deleting, setDeleting] = useState<Task | null>(null);

  useEffect(() => {
    const applyTheme = () => {
      const dark =
        prefs.theme === "dark" ||
        (prefs.theme === "system" && window.matchMedia("(prefers-color-scheme: dark)").matches);
      document.documentElement.classList.toggle("dark", dark);
    };

    applyTheme();
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    media.addEventListener("change", applyTheme);
    return () => media.removeEventListener("change", applyTheme);
  }, [prefs.theme]);

  const visibleTasks = useMemo(() => {
    const q = query.trim().toLowerCase();
    const priorityWeight: Record<Priority, number> = { high: 3, medium: 2, low: 1 };

    return tasks
      .filter((task) => {
        const matchesQuery =
          !q ||
          task.title.toLowerCase().includes(q) ||
          task.notes.toLowerCase().includes(q);
        const matchesStatus =
          prefs.status === "all" ||
          (prefs.status === "done" ? task.done : !task.done);
        const matchesPriority = prefs.priority === "all" || task.priority === prefs.priority;
        return matchesQuery && matchesStatus && matchesPriority;
      })
      .sort((a, b) => {
        if (prefs.sort === "priority") return priorityWeight[b.priority] - priorityWeight[a.priority];
        if (prefs.sort === "due") {
          const ad = a.dueDate || "9999-12-31";
          const bd = b.dueDate || "9999-12-31";
          return ad.localeCompare(bd);
        }
        return Date.parse(b.createdAt) - Date.parse(a.createdAt);
      });
  }, [prefs, query, tasks]);

  const stats = useMemo(() => {
    const done = tasks.filter((task) => task.done).length;
    return { total: tasks.length, done, open: tasks.length - done };
  }, [tasks]);

  function saveTask(task: Task) {
    const clean = { ...task, title: task.title.trim(), notes: task.notes.trim() };
    if (!clean.title) return;
    setTasks((current) => {
      const exists = current.some((item) => item.id === clean.id);
      return exists ? current.map((item) => (item.id === clean.id ? clean : item)) : [clean, ...current];
    });
    setEditing(null);
  }

  function removeTask(id: string) {
    setTasks((current) => current.filter((task) => task.id !== id));
    setDeleting(null);
  }

  return (
    <main className="min-h-screen bg-slate-50 px-4 py-8 text-slate-950 transition-colors dark:bg-slate-950 dark:text-slate-50">
      <div className="mx-auto max-w-6xl space-y-6">
        <header className="flex flex-col gap-4 rounded-3xl bg-white p-6 shadow-sm ring-1 ring-slate-200 dark:bg-slate-900 dark:ring-slate-800 md:flex-row md:items-center md:justify-between">
          <div>
            <p className="text-sm font-medium uppercase tracking-wide text-indigo-600 dark:text-indigo-400">
              Workspace
            </p>
            <h1 className="mt-1 text-3xl font-bold tracking-tight">Task Manager</h1>
            <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
              {stats.open} open, {stats.done} completed, {stats.total} total
            </p>
          </div>

          <div className="flex flex-wrap gap-2">
            <select
              value={prefs.theme}
              onChange={(event) => setPrefs((p) => ({ ...p, theme: event.target.value as Theme }))}
              className="rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-950"
              aria-label="Theme"
            >
              <option value="system">System theme</option>
              <option value="light">Light theme</option>
              <option value="dark">Dark theme</option>
            </select>
            <button
              onClick={() => setEditing(emptyTask())}
              className="rounded-xl bg-indigo-600 px-4 py-2 text-sm font-semibold text-white shadow-sm hover:bg-indigo-500"
            >
              New task
            </button>
          </div>
        </header>

        <section className="grid gap-3 rounded-3xl bg-white p-4 shadow-sm ring-1 ring-slate-200 dark:bg-slate-900 dark:ring-slate-800 md:grid-cols-[1fr_repeat(3,auto)]">
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search by title or notes..."
            className="rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 dark:border-slate-700 dark:bg-slate-950 dark:focus:ring-indigo-950"
          />
          <select
            value={prefs.status}
            onChange={(event) => setPrefs((p) => ({ ...p, status: event.target.value as Status }))}
            className="rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-950"
          >
            <option value="all">All statuses</option>
            <option value="open">Open</option>
            <option value="done">Completed</option>
          </select>
          <select
            value={prefs.priority}
            onChange={(event) => setPrefs((p) => ({ ...p, priority: event.target.value as Prefs["priority"] }))}
            className="rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-950"
          >
            <option value="all">All priorities</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
          <select
            value={prefs.sort}
            onChange={(event) => setPrefs((p) => ({ ...p, sort: event.target.value as Prefs["sort"] }))}
            className="rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-950"
          >
            <option value="newest">Newest first</option>
            <option value="due">Due date</option>
            <option value="priority">Priority</option>
          </select>
        </section>

        <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {visibleTasks.map((task) => (
            <article
              key={task.id}
              className="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 dark:bg-slate-900 dark:ring-slate-800"
            >
              <div className="flex items-start justify-between gap-3">
                <label className="flex min-w-0 items-start gap-3">
                  <input
                    type="checkbox"
                    checked={task.done}
                    onChange={() =>
                      setTasks((current) =>
                        current.map((item) => (item.id === task.id ? { ...item, done: !item.done } : item)),
                      )
                    }
                    className="mt-1 size-4 rounded border-slate-300 text-indigo-600"
                  />
                  <span className="min-w-0">
                    <span className={`block font-semibold ${task.done ? "text-slate-400 line-through" : ""}`}>
                      {task.title}
                    </span>
                    {task.notes && (
                      <span className="mt-1 block text-sm text-slate-600 dark:text-slate-400">{task.notes}</span>
                    )}
                  </span>
                </label>
                <span
                  className={`rounded-full px-2.5 py-1 text-xs font-semibold ${
                    task.priority === "high"
                      ? "bg-rose-100 text-rose-700 dark:bg-rose-950 dark:text-rose-300"
                      : task.priority === "medium"
                        ? "bg-amber-100 text-amber-700 dark:bg-amber-950 dark:text-amber-300"
                        : "bg-emerald-100 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300"
                  }`}
                >
                  {task.priority}
                </span>
              </div>

              <div className="mt-5 flex items-center justify-between gap-3 text-sm text-slate-500 dark:text-slate-400">
                <span>{task.dueDate ? `Due ${task.dueDate}` : "No due date"}</span>
                <div className="flex gap-2">
                  <button onClick={() => setEditing(task)} className="font-medium text-indigo-600 hover:text-indigo-500">
                    Edit
                  </button>
                  <button onClick={() => setDeleting(task)} className="font-medium text-rose-600 hover:text-rose-500">
                    Delete
                  </button>
                </div>
              </div>
            </article>
          ))}
        </section>

        {!visibleTasks.length && (
          <div className="rounded-3xl border border-dashed border-slate-300 p-10 text-center text-slate-500 dark:border-slate-700 dark:text-slate-400">
            No tasks match your current search and filters.
          </div>
        )}
      </div>

      {editing && <TaskModal task={editing} onClose={() => setEditing(null)} onSave={saveTask} />}

      {deleting && (
        <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4">
          <div className="w-full max-w-md rounded-3xl bg-white p-6 shadow-xl dark:bg-slate-900">
            <h2 className="text-xl font-bold">Delete task?</h2>
            <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">
              “{deleting.title}” will be permanently removed.
            </p>
            <div className="mt-6 flex justify-end gap-2">
              <button onClick={() => setDeleting(null)} className="rounded-xl px-4 py-2 text-sm font-semibold hover:bg-slate-100 dark:hover:bg-slate-800">
                Cancel
              </button>
              <button onClick={() => removeTask(deleting.id)} className="rounded-xl bg-rose-600 px-4 py-2 text-sm font-semibold text-white hover:bg-rose-500">
                Delete
              </button>
            </div>
          </div>
        </div>
      )}
    </main>
  );
}

function TaskModal({
  task,
  onClose,
  onSave,
}: {
  task: Task;
  onClose: () => void;
  onSave: (task: Task) => void;
}) {
  const [draft, setDraft] = useState(task);

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSave(draft);
  }

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4">
      <form onSubmit={submit} className="w-full max-w-lg rounded-3xl bg-white p-6 shadow-xl dark:bg-slate-900">
        <div className="flex items-start justify-between gap-4">
          <div>
            <h2 className="text-xl font-bold">{task.title ? "Edit task" : "Create task"}</h2>
            <p className="mt-1 text-sm text-slate-600 dark:text-slate-400">Capture the work, priority, and deadline.</p>
          </div>
          <button type="button" onClick={onClose} className="rounded-lg px-2 py-1 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">
            ✕
          </button>
        </div>

        <div className="mt-6 space-y-4">
          <label className="block text-sm font-medium">
            Title
            <input
              autoFocus
              required
              value={draft.title}
              onChange={(event) => setDraft({ ...draft, title: event.target.value })}
              className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 dark:border-slate-700 dark:bg-slate-950"
            />
          </label>
          <label className="block text-sm font-medium">
            Notes
            <textarea
              value={draft.notes}
              onChange={(event) => setDraft({ ...draft, notes: event.target.value })}
              rows={3}
              className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 dark:border-slate-700 dark:bg-slate-950"
            />
          </label>
          <div className="grid gap-4 sm:grid-cols-2">
            <label className="block text-sm font-medium">
              Priority
              <select
                value={draft.priority}
                onChange={(event) => setDraft({ ...draft, priority: event.target.value as Priority })}
                className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-950"
              >
                <option value="high">High</option>
                <option value="medium">Medium</option>
                <option value="low">Low</option>
              </select>
            </label>
            <label className="block text-sm font-medium">
              Due date
              <input
                type="date"
                value={draft.dueDate}
                onChange={(event) => setDraft({ ...draft, dueDate: event.target.value })}
                className="mt-1 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 dark:border-slate-700 dark:bg-slate-950"
              />
            </label>
          </div>
          <label className="flex items-center gap-2 text-sm">
            <input
              type="checkbox"
              checked={draft.done}
              onChange={(event) => setDraft({ ...draft, done: event.target.checked })}
              className="size-4 rounded border-slate-300 text-indigo-600"
            />
            Completed
          </label>
        </div>

        <div className="mt-6 flex justify-end gap-2">
          <button type="button" onClick={onClose} className="rounded-xl px-4 py-2 text-sm font-semibold hover:bg-slate-100 dark:hover:bg-slate-800">
            Cancel
          </button>
          <button type="submit" className="rounded-xl bg-indigo-600 px-4 py-2 text-sm font-semibold text-white hover:bg-indigo-500">
            Save task
          </button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";

type Priority = "low" | "medium" | "high";
type Status = "todo" | "in-progress" | "done";
interface Task { id: string; title: string; description: string; priority: Priority; status: Status; createdAt: number; }

const STORAGE_KEY = "tasks_v1";
const PREFS_KEY = "ui_prefs_v1";
const uid = () => Math.random().toString(36).slice(2);
const priorityColor: Record<Priority, string> = { low: "#22c55e", medium: "#f59e0b", high: "#ef4444" };

export default function Page() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState<Status | "all">("all");
  const [filterPriority, setFilterPriority] = useState<Priority | "all">("all");
  const [dark, setDark] = useState(false);
  const [modal, setModal] = useState<{ open: boolean; task?: Task }>({ open: false });
  const [form, setForm] = useState({ title: "", description: "", priority: "medium" as Priority, status: "todo" as Status });

  useEffect(() => {
    try { setTasks(JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]")); } catch { setTasks([]); }
    try { const p = JSON.parse(localStorage.getItem(PREFS_KEY) || "{}"); setDark(!!p.dark); } catch {}
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); }, [tasks]);
  useEffect(() => { localStorage.setItem(PREFS_KEY, JSON.stringify({ dark })); document.body.style.background = dark ? "#111" : "#f8fafc"; }, [dark]);

  const openCreate = () => { setForm({ title: "", description: "", priority: "medium", status: "todo" }); setModal({ open: true }); };
  const openEdit = (t: Task) => { setForm({ title: t.title, description: t.description, priority: t.priority, status: t.status }); setModal({ open: true, task: t }); };
  const closeModal = () => setModal({ open: false });

  const saveTask = useCallback(() => {
    if (!form.title.trim()) return;
    if (modal.task) {
      setTasks(ts => ts.map(t => t.id === modal.task!.id ? { ...t, ...form } : t));
    } else {
      setTasks(ts => [...ts, { id: uid(), ...form, createdAt: Date.now() }]);
    }
    closeModal();
  }, [form, modal.task]);

  const deleteTask = (id: string) => setTasks(ts => ts.filter(t => t.id !== id));

  const visible = tasks.filter(t =>
    (filterStatus === "all" || t.status === filterStatus) &&
    (filterPriority === "all" || t.priority === filterPriority) &&
    (t.title.toLowerCase().includes(search.toLowerCase()) || t.description.toLowerCase().includes(search.toLowerCase()))
  ).sort((a, b) => b.createdAt - a.createdAt);

  const bg = dark ? "#1e1e2e" : "#fff";
  const fg = dark ? "#cdd6f4" : "#1e293b";
  const card = dark ? "#2a2a3e" : "#f1f5f9";
  const border = dark ? "#44475a" : "#e2e8f0";
  const inputStyle = { background: dark ? "#313244" : "#fff", color: fg, border: `1px solid ${border}`, borderRadius: 6, padding: "6px 10px", fontSize: 14, outline: "none", width: "100%" };
  const btnPrimary = { background: "#6366f1", color: "#fff", border: "none", borderRadius: 6, padding: "7px 16px", cursor: "pointer", fontSize: 14 };
  const btnGhost = { background: "transparent", color: fg, border: `1px solid ${border}`, borderRadius: 6, padding: "6px 12px", cursor: "pointer", fontSize: 13 };

  return (
    <div style={{ minHeight: "100vh", background: dark ? "#111827" : "#f8fafc", color: fg, fontFamily: "system-ui,sans-serif", padding: "24px 16px" }}>
      <div style={{ maxWidth: 860, margin: "0 auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 24 }}>
          <h1 style={{ margin: 0, fontSize: 26, fontWeight: 700 }}>Task Manager</h1>
          <div style={{ display: "flex", gap: 8 }}>
            <button style={btnGhost} onClick={() => setDark(d => !d)}>{dark ? "☀️ Light" : "🌙 Dark"}</button>
            <button style={btnPrimary} onClick={openCreate}>+ New Task</button>
          </div>
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
          <input style={{ ...inputStyle, width: 220 }} placeholder="Search tasks…" value={search} onChange={e => setSearch(e.target.value)} />
          {(["all","todo","in-progress","done"] as const).map(s => (
            <button key={s} style={{ ...btnGhost, background: filterStatus === s ? "#6366f1" : "transparent", color: filterStatus === s ? "#fff" : fg, borderColor: filterStatus === s ? "#6366f1" : border }} onClick={() => setFilterStatus(s)}>{s}</button>
          ))}
          {(["all","low","medium","high"] as const).map(p => (
            <button key={p} style={{ ...btnGhost, background: filterPriority === p ? "#6366f1" : "transparent", color: filterPriority === p ? "#fff" : fg, borderColor: filterPriority === p ? "#6366f1" : border }} onClick={() => setFilterPriority(p)}>{p}</button>
          ))}
        </div>

        {visible.length === 0 && <p style={{ textAlign: "center", opacity: 0.5, marginTop: 48 }}>No tasks found.</p>}
        <div style={{ display: "grid", gap: 12 }}>
          {visible.map(t => (
            <div key={t.id} style={{ background: card, border: `1px solid ${border}`, borderRadius: 10, padding: "14px 16px", display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                  <span style={{ width: 10, height: 10, borderRadius: "50%", background: priorityColor[t.priority], display: "inline-block" }} />
                  <strong style={{ fontSize: 15 }}>{t.title}</strong>
                  <span style={{ fontSize: 11, background: dark ? "#44475a" : "#e2e8f0", borderRadius: 4, padding: "2px 7px" }}>{t.status}</span>
                </div>
                {t.description && <p style={{ margin: 0, fontSize: 13, opacity: 0.7 }}>{t.description}</p>}
              </div>
              <div style={{ display: "flex", gap: 6, marginLeft: 12 }}>
                <button style={btnGhost} onClick={() => openEdit(t)}>Edit</button>
                <button style={{ ...btnGhost, color: "#ef4444", borderColor: "#ef4444" }} onClick={() => deleteTask(t.id)}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {modal.open && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }} onClick={closeModal}>
          <div style={{ background: bg, border: `1px solid ${border}`, borderRadius: 12, padding: 28, width: "100%", maxWidth: 440, boxShadow: "0 20px 60px rgba(0,0,0,0.3)" }} onClick={e => e.stopPropagation()}>
            <h2 style={{ margin: "0 0 20px", fontSize: 18 }}>{modal.task ? "Edit Task" : "New Task"}</h2>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <input style={inputStyle} placeholder="Title *" value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} />
              <textarea style={{ ...inputStyle, resize: "vertical", minHeight: 72 }} placeholder="Description" value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
              <select style={inputStyle} value={form.priority} onChange={e => setForm(f => ({ ...f, priority: e.target.value as Priority }))}>
                <option value="low">Low Priority</option><option value="medium">Medium Priority</option><option value="high">High Priority</option>
              </select>
              <select style={inputStyle} value={form.status} onChange={e => setForm(f => ({ ...f, status: e.target.value as Status }))}>
                <option value="todo">To Do</option><option value="in-progress">In Progress</option><option value="done">Done</option>
              </select>
              <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", marginTop: 4 }}>
                <button style={btnGhost} onClick={closeModal}>Cancel</button>
                <button style={btnPrimary} onClick={saveTask}>{modal.task ? "Save Changes" : "Create Task"}</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Search, Edit2, Trash2, Check, X, Moon, Sun } from 'lucide-react';

interface Task {
  id: string;
  title: string;
  description: string;
  completed: boolean;
  createdAt: number;
}

type FilterType = 'all' | 'pending' | 'completed';
type Theme = 'light' | 'dark';

export default function TaskManager() {
  const [mounted, setMounted] = useState(false);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [theme, setTheme] = useState<Theme>('light');
  const [searchQuery, setSearchQuery] = useState('');
  const [filter, setFilter] = useState<FilterType>('all');

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [formData, setFormData] = useState({ title: '', description: '' });

  useEffect(() => {
    const savedTheme = (localStorage.getItem('task-theme') as Theme) || 'light';
    const savedTasks = localStorage.getItem('task-data');
    setTheme(savedTheme);
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted) return;
    localStorage.setItem('task-theme', theme);
    localStorage.setItem('task-data', JSON.stringify(tasks));

    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [theme, tasks, mounted]);

  const filteredTasks = useMemo(() => {
    return tasks
      .filter((task) => {
        if (filter === 'completed') return task.completed;
        if (filter === 'pending') return !task.completed;
        return true;
      })
      .filter((task) => 
        task.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        task.description.toLowerCase().includes(searchQuery.toLowerCase())
      )
      .sort((a, b) => b.createdAt - a.createdAt);
  }, [tasks, filter, searchQuery]);

  const handleSaveTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title.trim()) return;

    if (editingTask) {
      setTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...formData } : t));
    } else {
      const newTask: Task = {
        id: crypto.randomUUID(),
        title: formData.title.trim(),
        description: formData.description.trim(),
        completed: false,
        createdAt: Date.now(),
      };
      setTasks([...tasks, newTask]);
    }
    closeModal();
  };

  const toggleStatus = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const openModal = (task?: Task) => {
    if (task) {
      setEditingTask(task);
      setFormData({ title: task.title, description: task.description });
    } else {
      setEditingTask(null);
      setFormData({ title: '', description: '' });
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingTask(null);
    setFormData({ title: '', description: '' });
  };

  if (!mounted) return null;

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 transition-colors duration-200 p-4 sm:p-8">
      <div className="max-w-4xl mx-auto space-y-6">
        <header className="flex items-center justify-between">
          <h1 className="text-3xl font-bold tracking-tight">Tasks</h1>
          <button
            onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
            className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-800 transition-colors"
            aria-label="Toggle theme"
          >
            {theme === 'light' ? <Moon size={24} /> : <Sun size={24} />}
          </button>
        </header>

        <div className="flex flex-col sm:flex-row gap-4 items-center justify-between bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700">
          <div className="relative flex-1 w-full">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              placeholder="Search tasks..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-transparent focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div className="flex gap-4 w-full sm:w-auto">
            <select
              value={filter}
              onChange={(e) => setFilter(e.target.value as FilterType)}
              className="flex-1 sm:flex-none px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-transparent focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All</option>
              <option value="pending">Pending</option>
              <option value="completed">Completed</option>
            </select>
            <button
              onClick={() => openModal()}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors font-medium"
            >
              <Plus size={20} />
              <span className="hidden sm:inline">Add Task</span>
            </button>
          </div>
        </div>

        <div className="space-y-4">
          {filteredTasks.length === 0 ? (
            <div className="text-center py-12 text-gray-500 dark:text-gray-400">
              No tasks found. Create one to get started!
            </div>
          ) : (
            filteredTasks.map((task) => (
              <div
                key={task.id}
                className={`flex items-start gap-4 p-4 rounded-xl border transition-all ${
                  task.completed
                    ? 'bg-gray-50 dark:bg-gray-800/50 border-gray-200 dark:border-gray-700 opacity-75'
                    : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-700 shadow-sm'
                }`}
              >
                <button
                  onClick={() => toggleStatus(task.id)}
                  className={`mt-1 flex-shrink-0 w-6 h-6 rounded-full border-2 flex items-center justify-center transition-colors ${
                    task.completed
                      ? 'bg-green-500 border-green-500 text-white'
                      : 'border-gray-300 dark:border-gray-500 hover:border-blue-500'
                  }`}
                >
                  {task.completed && <Check size={14} strokeWidth={3} />}
                </button>
                <div className="flex-1 min-w-0">
                  <h3 className={`text-lg font-semibold truncate ${task.completed ? 'line-through text-gray-500 dark:text-gray-400' : ''}`}>
                    {task.title}
                  </h3>
                  {task.description && (
                    <p className="text-gray-600 dark:text-gray-300 mt-1 text-sm break-words">
                      {task.description}
                    </p>
                  )}
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  <button onClick={() => openModal(task)} className="p-2 text-gray-400 hover:text-blue-500 transition-colors">
                    <Edit2 size={18} />
                  </button>
                  <button onClick={() => deleteTask(task.id)} className="p-2 text-gray-400 hover:text-red-500 transition-colors">
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-gray-800 w-full max-w-md rounded-2xl shadow-xl overflow-hidden">
            <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-700">
              <h2 className="text-xl font-semibold">{editingTask ? 'Edit Task' : 'New Task'}</h2>
              <button onClick={closeModal} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSaveTask} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Title</label>
                <input
                  type="text"
                  required
                  autoFocus
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-transparent focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="Task title"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Description (Optional)</label>
                <textarea
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  className="w-full px-4 py-2 rounded-lg border border-gray-200 dark:border-gray-600 bg-transparent focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none h-24"
                  placeholder="Add details..."
                />
              </div>
              <div className="flex justify-end gap-3 pt-4">
                <button
                  type="button"
                  onClick={closeModal}
                  className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors font-medium"
                >
                  {editingTask ? 'Save Changes' : 'Create Task'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { signIn, signOut, useSession } from 'next-auth/react';

type ChatMessage = {
  id: string;
  body: string;
  userId: string;
  userName: string;
  userImage?: string | null;
  createdAt: string;
  pending?: boolean;
};

type SocketEvent =
  | { type: 'message'; message: ChatMessage }
  | { type: 'typing'; userId: string; userName: string; isTyping: boolean };

const draftKey = (userId?: string | null) => `chat:draft:${userId ?? 'guest'}`;

export default function Page() {
  const { data: session, status } = useSession();
  const user = session?.user;
  const userId = (user as { id?: string } | undefined)?.id ?? user?.email ?? null;

  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [draft, setDraft] = useState('');
  const [typing, setTyping] = useState<Record<string, { name: string; until: number }>>({});
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [connected, setConnected] = useState(false);

  const socketRef = useRef<WebSocket | null>(null);
  const bottomRef = useRef<HTMLDivElement | null>(null);
  const typingTimerRef = useRef<number | null>(null);
  const lastTypingSentRef = useRef(false);

  const mergeMessage = useCallback((message: ChatMessage) => {
    setMessages((current) => {
      const withoutDuplicate = current.filter(
        (item) => item.id !== message.id && !(item.pending && item.body === message.body && item.userId === message.userId),
      );
      return [...withoutDuplicate, message].sort(
        (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime(),
      );
    });
  }, []);

  const sendTyping = useCallback((isTyping: boolean) => {
    const socket = socketRef.current;
    if (!socket || socket.readyState !== WebSocket.OPEN || lastTypingSentRef.current === isTyping) return;
    socket.send(JSON.stringify({ type: 'typing', isTyping }));
    lastTypingSentRef.current = isTyping;
  }, []);

  useEffect(() => {
    const saved = (localStorage.getItem('theme') as 'light' | 'dark' | null) ?? 'light';
    setTheme(saved);
    document.documentElement.classList.toggle('dark', saved === 'dark');
  }, []);

  useEffect(() => {
    if (!userId) return;
    setDraft(localStorage.getItem(draftKey(userId)) ?? '');
  }, [userId]);

  useEffect(() => {
    if (!userId) return;
    localStorage.setItem(draftKey(userId), draft);
  }, [draft, userId]);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    if (status !== 'authenticated') return;

    let active = true;
    fetch('/api/chat/messages', { credentials: 'include' })
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error('Failed to load messages'))))
      .then((history: ChatMessage[]) => active && setMessages(history))
      .catch(() => active && setMessages([]));

    const url =
      process.env.NEXT_PUBLIC_CHAT_WS_URL ??
      `${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}/api/chat/ws`;
    const socket = new WebSocket(url);
    socketRef.current = socket;

    socket.onopen = () => setConnected(true);
    socket.onclose = () => {
      setConnected(false);
      lastTypingSentRef.current = false;
    };
    socket.onmessage = (event) => {
      const payload = JSON.parse(event.data) as SocketEvent;
      if (payload.type === 'message') mergeMessage(payload.message);
      if (payload.type === 'typing' && payload.userId !== userId) {
        setTyping((current) => {
          const next = { ...current };
          if (payload.isTyping) next[payload.userId] = { name: payload.userName, until: Date.now() + 3500 };
          else delete next[payload.userId];
          return next;
        });
      }
    };

    return () => {
      active = false;
      socket.close();
    };
  }, [mergeMessage, status, userId]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages.length]);

  useEffect(() => {
    const interval = window.setInterval(() => {
      setTyping((current) =>
        Object.fromEntries(Object.entries(current).filter(([, value]) => value.until > Date.now())),
      );
    }, 1000);
    return () => window.clearInterval(interval);
  }, []);

  const typingText = useMemo(() => {
    const names = Object.values(typing).map((item) => item.name);
    if (!names.length) return '';
    if (names.length === 1) return `${names[0]} is typing…`;
    if (names.length === 2) return `${names[0]} and ${names[1]} are typing…`;
    return 'Several people are typing…';
  }, [typing]);

  const onDraftChange = (value: string) => {
    setDraft(value);
    sendTyping(Boolean(value.trim()));
    if (typingTimerRef.current) window.clearTimeout(typingTimerRef.current);
    typingTimerRef.current = window.setTimeout(() => sendTyping(false), 1800);
  };

  const sendMessage = async (event: FormEvent) => {
    event.preventDefault();
    const body = draft.trim();
    if (!body || !userId || !user) return;

    const optimistic: ChatMessage = {
      id: `local-${crypto.randomUUID()}`,
      body,
      userId,
      userName: user.name ?? user.email ?? 'You',
      userImage: user.image,
      createdAt: new Date().toISOString(),
      pending: true,
    };

    setDraft('');
    sendTyping(false);
    mergeMessage(optimistic);

    const response = await fetch('/api/chat/messages', {
      method: 'POST',
      credentials: 'include',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ body }),
    });

    if (response.ok) mergeMessage(await response.json());
    else setMessages((current) => current.filter((message) => message.id !== optimistic.id));
  };

  if (status === 'loading') {
    return <main className="grid min-h-screen place-items-center bg-slate-50 text-slate-900 dark:bg-slate-950 dark:text-slate-100">Loading chat…</main>;
  }

  if (status !== 'authenticated') {
    return (
      <main className="grid min-h-screen place-items-center bg-slate-50 p-6 text-slate-900 dark:bg-slate-950 dark:text-slate-100">
        <section className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-8 text-center shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <h1 className="text-3xl font-semibold">Realtime Chat</h1>
          <p className="mt-3 text-slate-600 dark:text-slate-400">Sign in to view history, send messages, and see who is typing.</p>
          <button onClick={() => signIn()} className="mt-6 w-full rounded-2xl bg-blue-600 px-4 py-3 font-medium text-white hover:bg-blue-700">
            Sign in to continue
          </button>
        </section>
      </main>
    );
  }

  return (
    <main className="flex min-h-screen bg-slate-50 text-slate-900 dark:bg-slate-950 dark:text-slate-100">
      <section className="mx-auto flex h-screen w-full max-w-4xl flex-col border-x border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900">
        <header className="flex items-center justify-between border-b border-slate-200 px-5 py-4 dark:border-slate-800">
          <div>
            <h1 className="text-xl font-semibold">Realtime Chat</h1>
            <p className="text-sm text-slate-500 dark:text-slate-400">{connected ? 'Connected' : 'Reconnecting…'}</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setTheme((value) => (value === 'dark' ? 'light' : 'dark'))}
              className="rounded-xl border border-slate-200 px-3 py-2 text-sm dark:border-slate-700"
            >
              {theme === 'dark' ? 'Light' : 'Dark'}
            </button>
            <button onClick={() => signOut()} className="rounded-xl bg-slate-900 px-3 py-2 text-sm text-white dark:bg-slate-100 dark:text-slate-900">
              Sign out
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-5 py-6">
          {messages.length === 0 ? (
            <div className="grid h-full place-items-center text-center text-slate-500">No messages yet. Start the conversation.</div>
          ) : (
            <div className="space-y-4">
              {messages.map((message) => {
                const mine = message.userId === userId;
                return (
                  <article key={message.id} className={`flex gap-3 ${mine ? 'justify-end' : 'justify-start'}`}>
                    {!mine && (
                      <img src={message.userImage ?? '/avatar.png'} alt="" className="mt-1 h-9 w-9 rounded-full bg-slate-200 object-cover dark:bg-slate-800" />
                    )}
                    <div className={`max-w-[75%] rounded-2xl px-4 py-3 ${mine ? 'bg-blue-600 text-white' : 'bg-slate-100 dark:bg-slate-800'}`}>
                      <div className="mb-1 flex items-center gap-2 text-xs opacity-75">
                        <span>{mine ? 'You' : message.userName}</span>
                        <time>{new Date(message.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</time>
                        {message.pending && <span>Sending…</span>}
                      </div>
                      <p className="whitespace-pre-wrap break-words">{message.body}</p>
                    </div>
                  </article>
                );
              })}
              <div ref={bottomRef} />
            </div>
          )}
        </div>

        <div className="min-h-6 px-5 text-sm text-slate-500 dark:text-slate-400">{typingText}</div>

        <form onSubmit={sendMessage} className="flex gap-3 border-t border-slate-200 p-4 dark:border-slate-800">
          <textarea
            value={draft}
            onChange={(event) => onDraftChange(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !event.shiftKey) sendMessage(event);
            }}
            placeholder="Write a message…"
            rows={1}
            className="max-h-36 flex-1 resize-none rounded-2xl border border-slate-200 bg-white px-4 py-3 outline-none focus:border-blue-500 dark:border-slate-700 dark:bg-slate-950"
          />
          <button disabled={!draft.trim()} className="rounded-2xl bg-blue-600 px-5 py-3 font-medium text-white disabled:cursor-not-allowed disabled:opacity-50">
            Send
          </button>
        </form>
      </section>
    </main>
  );
}

"use client";

import { useState, useEffect, useRef, useCallback } from "react";

type Message = { id: string; user: string; text: string; ts: number };
type Theme = "light" | "dark";

const STORAGE_DRAFT = "chat_draft";
const STORAGE_THEME = "chat_theme";
const STORAGE_USER = "chat_user";

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

const MOCK_HISTORY: Message[] = [
  { id: uid(), user: "alice", text: "Hey, anyone around?", ts: Date.now() - 60000 },
  { id: uid(), user: "bob", text: "Yeah, what's up!", ts: Date.now() - 45000 },
  { id: uid(), user: "alice", text: "Just testing the new chat 🚀", ts: Date.now() - 30000 },
];

export default function ChatPage() {
  const [authed, setAuthed] = useState(false);
  const [username, setUsername] = useState("");
  const [loginInput, setLoginInput] = useState("");
  const [messages, setMessages] = useState<Message[]>(MOCK_HISTORY);
  const [draft, setDraft] = useState("");
  const [theme, setTheme] = useState<Theme>("light");
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const bottomRef = useRef<HTMLDivElement>(null);
  const typingTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const simulateTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const savedTheme = (localStorage.getItem(STORAGE_THEME) as Theme) || "light";
    const savedUser = localStorage.getItem(STORAGE_USER);
    const savedDraft = localStorage.getItem(STORAGE_DRAFT) || "";
    setTheme(savedTheme);
    setDraft(savedDraft);
    if (savedUser) { setUsername(savedUser); setAuthed(true); }
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
    localStorage.setItem(STORAGE_THEME, theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem(STORAGE_DRAFT, draft);
  }, [draft]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const simulateTyping = useCallback(() => {
    const peer = "alice";
    setTypingUsers((u) => [...new Set([...u, peer])]);
    if (simulateTimer.current) clearTimeout(simulateTimer.current);
    simulateTimer.current = setTimeout(() => {
      setTypingUsers((u) => u.filter((x) => x !== peer));
      setMessages((m) => [
        ...m,
        { id: uid(), user: peer, text: "Looks good to me!", ts: Date.now() },
      ]);
    }, 2500);
  }, []);

  const handleLogin = () => {
    const name = loginInput.trim();
    if (!name) return;
    setUsername(name);
    setAuthed(true);
    localStorage.setItem(STORAGE_USER, name);
  };

  const handleSend = () => {
    const text = draft.trim();
    if (!text) return;
    setMessages((m) => [...m, { id: uid(), user: username, text, ts: Date.now() }]);
    setDraft("");
    localStorage.removeItem(STORAGE_DRAFT);
    simulateTyping();
  };

  const handleDraftChange = (val: string) => {
    setDraft(val);
    setTypingUsers((u) => [...new Set([...u, username])]);
    if (typingTimer.current) clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(() => {
      setTypingUsers((u) => u.filter((x) => x !== username));
    }, 1500);
  };

  const handleLogout = () => {
    setAuthed(false);
    setUsername("");
    localStorage.removeItem(STORAGE_USER);
  };

  const bg = theme === "dark" ? "#1a1a2e" : "#f0f4f8";
  const surface = theme === "dark" ? "#16213e" : "#ffffff";
  const text = theme === "dark" ? "#e0e0e0" : "#1a1a2e";
  const accent = "#4f8ef7";
  const bubble = (isMe: boolean) =>
    isMe ? accent : theme === "dark" ? "#2a2a4a" : "#e2e8f0";
  const bubbleText = (isMe: boolean) => (isMe ? "#fff" : text);

  if (!authed) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", background: bg }}>
        <div style={{ background: surface, padding: 32, borderRadius: 16, boxShadow: "0 4px 24px rgba(0,0,0,.15)", minWidth: 320, color: text }}>
          <h2 style={{ margin: "0 0 20px", fontSize: 22 }}>Join Chat</h2>
          <input
            autoFocus
            placeholder="Choose a username"
            value={loginInput}
            onChange={(e) => setLoginInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleLogin()}
            style={{ width: "100%", padding: "10px 14px", borderRadius: 8, border: "1px solid #ccc", fontSize: 15, boxSizing: "border-box", marginBottom: 14 }}
          />
          <button onClick={handleLogin} style={{ width: "100%", padding: "10px 0", background: accent, color: "#fff", border: "none", borderRadius: 8, fontSize: 15, cursor: "pointer" }}>
            Enter
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100vh", background: bg, color: text }}>
      <header style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 20px", background: surface, boxShadow: "0 1px 6px rgba(0,0,0,.1)" }}>
        <span style={{ fontWeight: 700, fontSize: 18 }}>💬 LiveChat</span>
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          <span style={{ fontSize: 13, opacity: 0.7 }}>@{username}</span>
          <button onClick={() => setTheme((t) => (t === "dark" ? "light" : "dark"))} style={{ background: "none", border: "1px solid #aaa", borderRadius: 6, padding: "4px 10px", cursor: "pointer", color: text, fontSize: 13 }}>
            {theme === "dark" ? "☀️ Light" : "🌙 Dark"}
          </button>
          <button onClick={handleLogout} style={{ background: "none", border: "1px solid #aaa", borderRadius: 6, padding: "4px 10px", cursor: "pointer", color: text, fontSize: 13 }}>
            Logout
          </button>
        </div>
      </header>

      <div style={{ flex: 1, overflowY: "auto", padding: "16px 20px", display: "flex", flexDirection: "column", gap: 10 }}>
        {messages.map((m) => {
          const isMe = m.user === username;
          return (
            <div key={m.id} style={{ display: "flex", flexDirection: "column", alignItems: isMe ? "flex-end" : "flex-start" }}>
              <span style={{ fontSize: 11, opacity: 0.55, marginBottom: 2 }}>{m.user} · {new Date(m.ts).toLocaleTimeString()}</span>
              <div style={{ background: bubble(isMe), color: bubbleText(isMe), padding: "9px 14px", borderRadius: isMe ? "16px 16px 4px 16px" : "16px 16px 16px 4px", maxWidth: "70%", fontSize: 14, lineHeight: 1.5 }}>
                {m.text}
              </div>
            </div>
          );
        })}
        {typingUsers.filter((u) => u !== username).length > 0 && (
          <div style={{ fontSize: 12, opacity: 0.6, fontStyle: "italic" }}>
            {typingUsers.filter((u) => u !== username).join(", ")} {typingUsers.filter((u) => u !== username).length === 1 ? "is" : "are"} typing…
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      <div style={{ padding: "12px 20px", background: surface, display: "flex", gap: 10, boxShadow: "0 -1px 6px rgba(0,0,0,.08)" }}>
        <input
          value={draft}
          onChange={(e) => handleDraftChange(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && !e.shiftKey && handleSend()}
          placeholder="Type a message…"
          style={{ flex: 1, padding: "10px 14px", borderRadius: 10, border: "1px solid #ccc", fontSize: 14, background: bg, color: text, outline: "none" }}
        />
        <button onClick={handleSend} style={{ padding: "10px 20px", background: accent, color: "#fff", border: "none", borderRadius: 10, fontSize: 14, cursor: "pointer", fontWeight: 600 }}>
          Send
        </button>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef } from 'react';

type Message = {
  id: string;
  text: string;
  sender: string;
  timestamp: number;
};

type Theme = 'light' | 'dark';

export default function ChatPage() {
  const [user, setUser] = useState<string>('');
  const [loginName, setLoginName] = useState('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [theme, setTheme] = useState<Theme>('light');
  const [isMounted, setIsMounted] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setIsMounted(true);
    const savedTheme = localStorage.getItem('chat-theme') as Theme;
    if (savedTheme) setTheme(savedTheme);

    const savedDraft = localStorage.getItem('chat-draft');
    if (savedDraft) setDraft(savedDraft);

    const savedUser = localStorage.getItem('chat-user');
    if (savedUser) setUser(savedUser);
  }, []);

  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('chat-draft', draft);
    }
  }, [draft, isMounted]);

  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('chat-theme', theme);
      if (theme === 'dark') {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
  }, [theme, isMounted]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginName.trim()) return;
    setUser(loginName.trim());
    localStorage.setItem('chat-user', loginName.trim());
  };

  const handleLogout = () => {
    setUser('');
    setMessages([]);
    localStorage.removeItem('chat-user');
  };

  const sendMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.trim()) return;

    const newMsg: Message = {
      id: crypto.randomUUID(),
      text: draft.trim(),
      sender: user,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, newMsg]);
    setDraft('');

    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages((prev) => [
        ...prev,
        {
          id: crypto.randomUUID(),
          text: `Echo: ${newMsg.text}`,
          sender: 'System Bot',
          timestamp: Date.now(),
        },
      ]);
    }, 1200 + Math.random() * 1000);
  };

  if (!isMounted) return null;

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white transition-colors duration-200">
        <form onSubmit={handleLogin} className="p-8 bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-md border border-gray-100 dark:border-gray-700">
          <div className="flex justify-between items-center mb-8">
            <h1 className="text-3xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-500 to-teal-400">
              Realtime Chat
            </h1>
            <button
              type="button"
              onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
              className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition"
            >
              {theme === 'light' ? '🌙' : '☀️'}
            </button>
          </div>
          <div className="space-y-4">
            <div>
              <label htmlFor="username" className="block text-sm font-medium mb-2 text-gray-700 dark:text-gray-300">
                Choose a username
              </label>
              <input
                id="username"
                type="text"
                value={loginName}
                onChange={(e) => setLoginName(e.target.value)}
                placeholder="e.g. Alex"
                className="w-full p-3 border rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none dark:bg-gray-900 dark:border-gray-600 transition-all"
                autoFocus
                required
              />
            </div>
            <button type="submit" className="w-full bg-blue-600 text-white p-3 rounded-xl font-semibold hover:bg-blue-700 transition-colors shadow-md hover:shadow-lg">
              Join Chat
            </button>
          </div>
        </form>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white transition-colors duration-200">
      <header className="flex items-center justify-between p-4 bg-white dark:bg-gray-800 shadow-sm border-b dark:border-gray-700 z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-teal-400 rounded-full flex items-center justify-center text-white font-bold shadow-sm">
            {user.charAt(0).toUpperCase()}
          </div>
          <div>
            <h2 className="font-semibold leading-tight">{user}</h2>
            <p className="text-xs text-green-500 flex items-center gap-1.5 font-medium">
              <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span> Online
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
            className="p-2 rounded-full hover:bg-gray-100 dark:hover:bg-gray-700 transition"
            aria-label="Toggle theme"
          >
            {theme === 'light' ? '🌙' : '☀️'}
          </button>
          <button 
            onClick={handleLogout} 
            className="px-4 py-2 text-sm font-medium text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
          >
            Logout
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6">
        {messages.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-gray-400 dark:text-gray-500 space-y-4">
            <div className="w-24 h-24 bg-gray-100 dark:bg-gray-800 rounded-full flex items-center justify-center text-4xl">
              👋
            </div>
            <p>No messages yet. Start the conversation!</p>
          </div>
        ) : (
          messages.map((msg) => {
            const isMe = msg.sender === user;
            return (
              <div key={msg.id} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                <span className="text-xs text-gray-500 dark:text-gray-400 mb-1.5 mx-1 font-medium">
                  {isMe ? 'You' : msg.sender}
                </span>
                <div
                  className={`max-w-[85%] sm:max-w-[75%] p-3.5 rounded-2xl shadow-sm ${
                    isMe
                      ? 'bg-blue-600 text-white rounded-tr-sm'
                      : 'bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-tl-sm'
                  }`}
                >
                  <p className="leading-relaxed break-words">{msg.text}</p>
                </div>
                <span className="text-[10px] text-gray-400 mt-1.5 mx-1">
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
            );
          })
        )}

        {isTyping && (
          <div className="flex flex-col items-start animate-in fade-in duration-200">
            <span className="text-xs text-gray-500 dark:text-gray-400 mb-1.5 mx-1 font-medium">System Bot</span>
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 p-4 rounded-2xl rounded-tl-sm shadow-sm flex gap-1.5 items-center">
              <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></span>
              <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.15s' }}></span>
              <span className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.3s' }}></span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} className="h-1" />
      </main>

      <footer className="p-4 bg-white dark:bg-gray-800 border-t dark:border-gray-700 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
        <form onSubmit={sendMessage} className="flex gap-3 max-w-5xl mx-auto">
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Type your message..."
            className="flex-1 p-3.5 px-5 bg-gray-100 dark:bg-gray-900 border-transparent rounded-full focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-white dark:focus:bg-gray-800 transition-all"
          />
          <button
            type="submit"
            disabled={!draft.trim()}
            className="bg-blue-600 text-white px-6 py-3.5 rounded-full font-semibold hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm flex items-center gap-2"
          >
            <span>Send</span>
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </form>
      </footer>
    </div>
  );
}

import React, { useMemo, useState } from 'react';
import { FlatList, Modal, Pressable, SafeAreaView, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { Ionicons } from '@expo/vector-icons';

type Attendee = { id: string; name: string; role: string };
type EventItem = {
  id: string;
  title: string;
  category: string;
  date: string;
  time: string;
  location: string;
  description: string;
  attendees: Attendee[];
  rsvped?: boolean;
};

const day = (offset: number) => {
  const d = new Date();
  d.setDate(d.getDate() + offset);
  return d.toISOString().slice(0, 10);
};

const me: Attendee = { id: 'me', name: 'You', role: 'Host' };
const categories = ['All', 'Music', 'Food', 'Sports', 'Tech', 'Community'];
const seedEvents: EventItem[] = [
  {
    id: '1',
    title: 'Riverside Jazz Night',
    category: 'Music',
    date: day(0),
    time: '7:30 PM',
    location: 'Riverside Amphitheater',
    description: 'Live quartet, food trucks, and sunset views by the river.',
    attendees: [{ id: 'a', name: 'Maya Chen', role: 'Organizer' }, { id: 'b', name: 'Leo Grant', role: 'Musician' }],
  },
  {
    id: '2',
    title: 'Startup Product Mixer',
    category: 'Tech',
    date: day(1),
    time: '6:00 PM',
    location: 'North Loop Labs',
    description: 'Meet founders, designers, and builders over lightning demos.',
    attendees: [{ id: 'c', name: 'Priya Shah', role: 'Founder' }, { id: 'd', name: 'Noah Kim', role: 'Designer' }],
    rsvped: true,
  },
  {
    id: '3',
    title: 'Saturday Market Tasting',
    category: 'Food',
    date: day(2),
    time: '10:00 AM',
    location: 'Central Farmers Market',
    description: 'Sample local coffee, pastries, cheeses, and seasonal produce.',
    attendees: [{ id: 'e', name: 'Amara Stone', role: 'Chef' }, { id: 'f', name: 'Ben Ortiz', role: 'Vendor' }],
  },
  {
    id: '4',
    title: 'Park 5K Social Run',
    category: 'Sports',
    date: day(3),
    time: '8:00 AM',
    location: 'Oak Park Trailhead',
    description: 'Casual pace 5K followed by smoothies at the clubhouse.',
    attendees: [{ id: 'g', name: 'Elena Ruiz', role: 'Coach' }],
  },
];

export default function HomeScreen() {
  const [events, setEvents] = useState(seedEvents);
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('All');
  const [date, setDate] = useState<string | null>(null);
  const [createOpen, setCreateOpen] = useState(false);
  const [notifyOpen, setNotifyOpen] = useState(false);
  const [profile, setProfile] = useState<Attendee | null>(null);
  const [draft, setDraft] = useState({ title: '', category: 'Community', date: day(1), time: '5:00 PM', location: '', description: '' });

  const calendar = useMemo(() => Array.from({ length: 7 }, (_, i) => day(i)), []);
  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return events.filter(e =>
      (category === 'All' || e.category === category) &&
      (!date || e.date === date) &&
      (!q || `${e.title} ${e.location} ${e.description}`.toLowerCase().includes(q)),
    ).sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`));
  }, [events, query, category, date]);

  const rsvp = (id: string) => setEvents(list => list.map(e => {
    if (e.id !== id) return e;
    const going = !e.rsvped;
    return { ...e, rsvped: going, attendees: going ? [me, ...e.attendees.filter(a => a.id !== 'me')] : e.attendees.filter(a => a.id !== 'me') };
  }));

  const createEvent = () => {
    if (!draft.title.trim() || !draft.location.trim()) return;
    setEvents([{ id: String(Date.now()), ...draft, attendees: [me], rsvped: true }, ...events]);
    setDraft({ title: '', category: 'Community', date: day(1), time: '5:00 PM', location: '', description: '' });
    setCreateOpen(false);
  };

  const notifications = [
    `${events.filter(e => e.rsvped).length} RSVP${events.filter(e => e.rsvped).length === 1 ? '' : 's'} confirmed`,
    `Next up: ${events.find(e => e.rsvped)?.title || 'browse an event to join'}`,
    'New community events were added near you',
  ];

  const renderEvent = ({ item }: { item: EventItem }) => (
    <View style={styles.card}>
      <View style={styles.cardTop}>
        <View style={styles.badge}><Text style={styles.badgeText}>{item.category}</Text></View>
        <Text style={styles.dateText}>{new Date(item.date).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })} · {item.time}</Text>
      </View>
      <Text style={styles.title}>{item.title}</Text>
      <Text style={styles.desc}>{item.description}</Text>
      <View style={styles.row}><Ionicons name="location-outline" size={16} color="#64748b" /><Text style={styles.meta}>{item.location}</Text></View>
      <View style={styles.attendees}>
        {item.attendees.slice(0, 4).map(a => (
          <Pressable key={a.id} onPress={() => setProfile(a)} style={styles.avatar}>
            <Text style={styles.avatarText}>{a.name.split(' ').map(p => p[0]).join('')}</Text>
          </Pressable>
        ))}
        <Text style={styles.meta}>{item.attendees.length} attending</Text>
      </View>
      <Pressable onPress={() => rsvp(item.id)} style={[styles.rsvp, item.rsvped && styles.rsvped]}>
        <Ionicons name={item.rsvped ? 'checkmark-circle' : 'add-circle-outline'} size={18} color={item.rsvped ? '#fff' : '#2563eb'} />
        <Text style={[styles.rsvpText, item.rsvped && styles.rsvpTextOn]}>{item.rsvped ? 'Going' : 'RSVP'}</Text>
      </Pressable>
    </View>
  );

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.header}>
        <View>
          <Text style={styles.kicker}>Plan together</Text>
          <Text style={styles.heading}>Discover events</Text>
        </View>
        <View style={styles.headerActions}>
          <Pressable onPress={() => setNotifyOpen(true)} style={styles.iconBtn}>
            <Ionicons name="notifications-outline" size={22} color="#0f172a" />
            <View style={styles.dot} />
          </Pressable>
          <Pressable onPress={() => setProfile(me)} style={styles.avatarLarge}><Text style={styles.avatarText}>Y</Text></Pressable>
        </View>
      </View>

      <View style={styles.search}>
        <Ionicons name="search" size={18} color="#64748b" />
        <TextInput value={query} onChangeText={setQuery} placeholder="Search events, venues, details" style={styles.input} placeholderTextColor="#94a3b8" />
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>
        {categories.map(c => <Pressable key={c} onPress={() => setCategory(c)} style={[styles.chip, category === c && styles.chipOn]}><Text style={[styles.chipText, category === c && styles.chipTextOn]}>{c}</Text></Pressable>)}
      </ScrollView>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.calendar}>
        <Pressable onPress={() => setDate(null)} style={[styles.day, !date && styles.dayOn]}><Text style={[styles.dayNum, !date && styles.dayTextOn]}>All</Text><Text style={[styles.dayLabel, !date && styles.dayTextOn]}>dates</Text></Pressable>
        {calendar.map(d => {
          const selected = date === d, count = events.filter(e => e.date === d).length;
          return <Pressable key={d} onPress={() => setDate(selected ? null : d)} style={[styles.day, selected && styles.dayOn]}>
            <Text style={[styles.dayLabel, selected && styles.dayTextOn]}>{new Date(d).toLocaleDateString(undefined, { weekday: 'short' })}</Text>
            <Text style={[styles.dayNum, selected && styles.dayTextOn]}>{new Date(d).getDate()}</Text>
            <Text style={[styles.dayLabel, selected && styles.dayTextOn]}>{count} event{count === 1 ? '' : 's'}</Text>
          </Pressable>;
        })}
      </ScrollView>

      <FlatList
        data={filtered}
        keyExtractor={i => i.id}
        renderItem={renderEvent}
        contentContainerStyle={styles.list}
        ListEmptyComponent={<Text style={styles.empty}>No events match your filters.</Text>}
      />

      <Pressable onPress={() => setCreateOpen(true)} style={styles.fab}><Ionicons name="add" size={30} color="#fff" /></Pressable>

      <Modal visible={createOpen} animationType="slide" transparent>
        <View style={styles.overlay}><View style={styles.sheet}>
          <View style={styles.sheetTop}><Text style={styles.sheetTitle}>Create event</Text><Pressable onPress={() => setCreateOpen(false)}><Ionicons name="close" size={24} /></Pressable></View>
          {(['title', 'time', 'location', 'description'] as const).map(k => (
            <TextInput key={k} value={draft[k]} onChangeText={v => setDraft({ ...draft, [k]: v })} placeholder={k[0].toUpperCase() + k.slice(1)} style={[styles.field, k === 'description' && styles.multiline]} multiline={k === 'description'} />
          ))}
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>
            {categories.slice(1).map(c => <Pressable key={c} onPress={() => setDraft({ ...draft, category: c })} style={[styles.chip, draft.category === c && styles.chipOn]}><Text style={[styles.chipText, draft.category === c && styles.chipTextOn]}>{c}</Text></Pressable>)}
          </ScrollView>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>
            {calendar.map(d => <Pressable key={d} onPress={() => setDraft({ ...draft, date: d })} style={[styles.chip, draft.date === d && styles.chipOn]}><Text style={[styles.chipText, draft.date === d && styles.chipTextOn]}>{new Date(d).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}</Text></Pressable>)}
          </ScrollView>
          <Pressable onPress={createEvent} style={styles.primary}><Text style={styles.primaryText}>Publish event</Text></Pressable>
        </View></View>
      </Modal>

      <Modal visible={notifyOpen} animationType="fade" transparent>
        <Pressable style={styles.overlay} onPress={() => setNotifyOpen(false)}><View style={styles.popover}>
          <Text style={styles.sheetTitle}>Notifications</Text>
          {notifications.map(n => <View key={n} style={styles.notice}><Ionicons name="sparkles-outline" size={18} color="#2563eb" /><Text style={styles.meta}>{n}</Text></View>)}
        </View></Pressable>
      </Modal>

      <Modal visible={!!profile} animationType="fade" transparent>
        <Pressable style={styles.overlay} onPress={() => setProfile(null)}><View style={styles.profile}>
          <View style={styles.avatarXL}><Text style={styles.avatarXLText}>{profile?.name.split(' ').map(p => p[0]).join('')}</Text></View>
          <Text style={styles.sheetTitle}>{profile?.name}</Text>
          <Text style={styles.meta}>{profile?.role}</Text>
          <Text style={styles.desc}>Active attendee with shared interests in local events, planning, and community meetups.</Text>
        </View></Pressable>
      </Modal>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: '#f8fafc' },
  header: { padding: 20, paddingBottom: 10, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  kicker: { color: '#2563eb', fontWeight: '700' },
  heading: { fontSize: 30, fontWeight: '800', color: '#0f172a' },
  headerActions: { flexDirection: 'row', gap: 10, alignItems: 'center' },
  iconBtn: { width: 42, height: 42, borderRadius: 21, backgroundColor: '#fff', alignItems: 'center', justifyContent: 'center' },
  dot: { position: 'absolute', right: 10, top: 9, width: 8, height: 8, borderRadius: 4, backgroundColor: '#ef4444' },
  search: { marginHorizontal: 20, marginBottom: 12, backgroundColor: '#fff', borderRadius: 16, paddingHorizontal: 14, height: 48, flexDirection: 'row', alignItems: 'center', gap: 8 },
