import React, { useState, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TextInput,
  TouchableOpacity,
  Modal,
  ScrollView,
  SafeAreaView,
  Alert,
  Image,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';

type Category = 'All' | 'Music' | 'Tech' | 'Sports' | 'Food' | 'Art';

interface Attendee { id: string; name: string; avatar: string; }
interface Event {
  id: string; title: string; date: string; location: string;
  category: Category; description: string; attendees: Attendee[];
  rsvped: boolean; image: string;
}

const CATEGORIES: Category[] = ['All', 'Music', 'Tech', 'Sports', 'Food', 'Art'];

const MOCK_EVENTS: Event[] = [
  { id: '1', title: 'Jazz Night Downtown', date: '2024-07-15 20:00', location: 'Blue Note Club, NYC', category: 'Music', description: 'An evening of smooth jazz with local artists.', attendees: [{ id: 'a1', name: 'Alice', avatar: 'https://i.pravatar.cc/40?img=1' }, { id: 'a2', name: 'Bob', avatar: 'https://i.pravatar.cc/40?img=2' }], rsvped: false, image: 'https://picsum.photos/seed/jazz/400/200' },
  { id: '2', title: 'React Native Summit', date: '2024-07-20 09:00', location: 'Tech Hub, SF', category: 'Tech', description: 'Deep dives into mobile development trends.', attendees: [{ id: 'a3', name: 'Carol', avatar: 'https://i.pravatar.cc/40?img=3' }], rsvped: true, image: 'https://picsum.photos/seed/tech/400/200' },
  { id: '3', title: 'City Marathon', date: '2024-07-25 07:00', location: 'Central Park, NYC', category: 'Sports', description: 'Annual 26.2 mile city marathon.', attendees: [{ id: 'a4', name: 'Dan', avatar: 'https://i.pravatar.cc/40?img=4' }, { id: 'a5', name: 'Eve', avatar: 'https://i.pravatar.cc/40?img=5' }, { id: 'a6', name: 'Frank', avatar: 'https://i.pravatar.cc/40?img=6' }], rsvped: false, image: 'https://picsum.photos/seed/marathon/400/200' },
  { id: '4', title: 'Food Truck Festival', date: '2024-08-01 12:00', location: 'Riverside Park, Chicago', category: 'Food', description: 'Over 50 food trucks from around the world.', attendees: [], rsvped: false, image: 'https://picsum.photos/seed/food/400/200' },
  { id: '5', title: 'Modern Art Expo', date: '2024-08-05 10:00', location: 'MoMA, NYC', category: 'Art', description: 'Showcasing emerging contemporary artists.', attendees: [{ id: 'a7', name: 'Grace', avatar: 'https://i.pravatar.cc/40?img=7' }], rsvped: true, image: 'https://picsum.photos/seed/art/400/200' },
];

export default function HomeScreen() {
  const [events, setEvents] = useState<Event[]>(MOCK_EVENTS);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState<Category>('All');
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [createVisible, setCreateVisible] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newLocation, setNewLocation] = useState('');

  const filtered = events.filter(e =>
    (activeCategory === 'All' || e.category === activeCategory) &&
    (e.title.toLowerCase().includes(search.toLowerCase()) || e.location.toLowerCase().includes(search.toLowerCase()))
  );

  const toggleRSVP = useCallback((id: string) => {
    setEvents(prev => prev.map(e => e.id === id ? { ...e, rsvped: !e.rsvped } : e));
    if (selectedEvent?.id === id) setSelectedEvent(prev => prev ? { ...prev, rsvped: !prev.rsvped } : null);
    Alert.alert('RSVP Updated', 'Your RSVP status has been saved.');
  }, [selectedEvent]);

  const createEvent = () => {
    if (!newTitle.trim()) { Alert.alert('Error', 'Title is required'); return; }
    const ev: Event = { id: Date.now().toString(), title: newTitle, date: '2024-09-01 18:00', location: newLocation || 'TBD', category: 'All', description: 'New event', attendees: [], rsvped: false, image: 'https://picsum.photos/seed/new/400/200' };
    setEvents(prev => [ev, ...prev]);
    setNewTitle(''); setNewLocation(''); setCreateVisible(false);
  };

  const renderEvent = ({ item }: { item: Event }) => (
    <TouchableOpacity style={styles.card} onPress={() => setSelectedEvent(item)}>
      <Image source={{ uri: item.image }} style={styles.cardImage} />
      <View style={styles.cardBody}>
        <View style={styles.row}>
          <Text style={styles.categoryBadge}>{item.category}</Text>
          {item.rsvped && <Text style={styles.rsvpBadge}>✓ Going</Text>}
        </View>
        <Text style={styles.cardTitle}>{item.title}</Text>
        <Text style={styles.cardMeta}><Ionicons name="calendar-outline" size={12} /> {item.date}</Text>
        <Text style={styles.cardMeta}><Ionicons name="location-outline" size={12} /> {item.location}</Text>
        <View style={styles.row}>
          {item.attendees.slice(0, 3).map(a => <Image key={a.id} source={{ uri: a.avatar }} style={styles.avatar} />)}
          {item.attendees.length > 3 && <Text style={styles.moreAttendees}>+{item.attendees.length - 3}</Text>}
        </View>
      </View>
    </TouchableOpacity>
  );

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Discover Events</Text>
        <TouchableOpacity onPress={() => Alert.alert('Profile', 'User profile coming soon!')}><Ionicons name="person-circle-outline" size={30} color="#6C63FF" /></TouchableOpacity>
      </View>
      <View style={styles.searchRow}>
        <Ionicons name="search-outline" size={18} color="#999" style={{ marginRight: 6 }} />
        <TextInput style={styles.searchInput} placeholder="Search events or locations..." value={search} onChangeText={setSearch} />
      </View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.categories}>
        {CATEGORIES.map(c => (
          <TouchableOpacity key={c} style={[styles.catBtn, activeCategory === c && styles.catBtnActive]} onPress={() => setActiveCategory(c)}>
            <Text style={[styles.catText, activeCategory === c && styles.catTextActive]}>{c}</Text>
          </TouchableOpacity>
        ))}
      </ScrollView>
      <FlatList data={filtered} keyExtractor={i => i.id} renderItem={renderEvent} contentContainerStyle={{ paddingBottom: 100 }} ListEmptyComponent={<Text style={styles.empty}>No events found.</Text>} />
      <TouchableOpacity style={styles.fab} onPress={() => setCreateVisible(true)}><Ionicons name="add" size={28} color="#fff" /></TouchableOpacity>

      <Modal visible={!!selectedEvent} animationType="slide" onRequestClose={() => setSelectedEvent(null)}>
        {selectedEvent && (
          <SafeAreaView style={styles.container}>
            <TouchableOpacity style={styles.backBtn} onPress={() => setSelectedEvent(null)}><Ionicons name="arrow-back" size={24} color="#6C63FF" /></TouchableOpacity>
            <ScrollView>
              <Image source={{ uri: selectedEvent.image }} style={styles.detailImage} />
              <View style={{ padding: 16 }}>
                <Text style={styles.detailTitle}>{selectedEvent.title}</Text>
                <Text style={styles.cardMeta}><Ionicons name="calendar-outline" size={14} /> {selectedEvent.date}</Text>
                <Text style={styles.cardMeta}><Ionicons name="location-outline" size={14} /> {selectedEvent.location}</Text>
                <Text style={styles.detailDesc}>{selectedEvent.description}</Text>
                <Text style={styles.sectionLabel}>Attendees ({selectedEvent.attendees.length})</Text>
                <View style={styles.row}>{selectedEvent.attendees.map(a => (<View key={a.id} style={styles.attendeeItem}><Image source={{ uri: a.avatar }} style={styles.avatarLg} /><Text style={styles.attendeeName}>{a.name}</Text></View>))}</View>
                <TouchableOpacity style={[styles.rsvpBtn, selectedEvent.rsvped && styles.rsvpBtnActive]} onPress={() => toggleRSVP(selectedEvent.id)}>
                  <Text style={styles.rsvpBtnText}>{selectedEvent.rsvped ? 'Cancel RSVP' : 'RSVP Now'}</Text>
                </TouchableOpacity>
              </View>
            </ScrollView>
          </SafeAreaView>
        )}
      </Modal>

      <Modal visible={createVisible} animationType="slide" transparent onRequestClose={() => setCreateVisible(false)}>
        <View style={styles.modalOverlay}>
          <View style={styles.modalBox}>
            <Text style={styles.modalTitle}>Create Event</Text>
            <TextInput style={styles.input} placeholder="Event Title" value={newTitle} onChangeText={setNewTitle} />
            <TextInput style={styles.input} placeholder="Location" value={newLocation} onChangeText={setNewLocation} />
            <TouchableOpacity style={styles.rsvpBtn} onPress={createEvent}><Text style={styles.rsvpBtnText}>Create</Text></TouchableOpacity>
            <TouchableOpacity onPress={() => setCreateVisible(false)}><Text style={styles.cancelText}>Cancel</Text></TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

