import React, { useState, useMemo } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TextInput,
  TouchableOpacity,
  Modal,
  Image,
  ScrollView,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';

type Event = {
  id: string;
  title: string;
  date: string;
  location: string;
  category: string;
  attendees: number;
  isRsvpd: boolean;
};

const MOCK_EVENTS: Event[] = [
  { id: '1', title: 'React Native Meetup', date: 'Oct 24, 6:00 PM', location: 'Tech Hub, SF', category: 'Tech', attendees: 42, isRsvpd: true },
  { id: '2', title: 'Indie Music Fest', date: 'Oct 26, 4:00 PM', location: 'Golden Gate Park', category: 'Music', attendees: 128, isRsvpd: false },
  { id: '3', title: 'Local Marathon', date: 'Nov 2, 7:00 AM', location: 'Downtown', category: 'Sports', attendees: 350, isRsvpd: false },
  { id: '4', title: 'Food Truck Fiesta', date: 'Nov 5, 12:00 PM', location: 'City Square', category: 'Food', attendees: 85, isRsvpd: true },
];

const CATEGORIES = ['All', 'Tech', 'Music', 'Sports', 'Food', 'Art'];

export default function HomeScreen() {
  const [events, setEvents] = useState<Event[]>(MOCK_EVENTS);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [isCalendarView, setIsCalendarView] = useState(false);
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  const filteredEvents = useMemo(() => {
    return events.filter(
      (e) =>
        (selectedCategory === 'All' || e.category === selectedCategory) &&
        e.title.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [events, searchQuery, selectedCategory]);

  const toggleRsvp = (id: string) => {
    setEvents((prev) =>
      prev.map((e) => (e.id === id ? { ...e, isRsvpd: !e.isRsvpd, attendees: e.isRsvpd ? e.attendees - 1 : e.attendees + 1 } : e))
    );
  };

  const renderEventCard = ({ item }: { item: Event }) => (
    <View style={styles.card}>
      <View style={styles.cardHeader}>
        <Text style={styles.cardTitle}>{item.title}</Text>
        <TouchableOpacity onPress={() => toggleRsvp(item.id)} style={[styles.rsvpBtn, item.isRsvpd && styles.rsvpdBtn]}>
          <Text style={[styles.rsvpText, item.isRsvpd && styles.rsvpdText]}>{item.isRsvpd ? 'Going' : 'RSVP'}</Text>
        </TouchableOpacity>
      </View>
      <View style={styles.cardRow}>
        <Ionicons name="calendar-outline" size={16} color="#666" />
        <Text style={styles.cardDetail}>{item.date}</Text>
      </View>
      <View style={styles.cardRow}>
        <Ionicons name="location-outline" size={16} color="#666" />
        <Text style={styles.cardDetail}>{item.location}</Text>
      </View>
      <View style={styles.cardRow}>
        <Ionicons name="people-outline" size={16} color="#666" />
        <Text style={styles.cardDetail}>{item.attendees} attending</Text>
      </View>
    </View>
  );

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Image source={{ uri: 'https://i.pravatar.cc/100?img=33' }} style={styles.avatar} />
        <Text style={styles.headerTitle}>Discover Events</Text>
        <TouchableOpacity style={styles.iconBtn}>
          <Ionicons name="notifications-outline" size={24} color="#333" />
          <View style={styles.badge} />
        </TouchableOpacity>
      </View>

      <View style={styles.searchContainer}>
        <View style={styles.searchInputContainer}>
          <Ionicons name="search" size={20} color="#999" />
          <TextInput
            style={styles.searchInput}
            placeholder="Search events..."
            value={searchQuery}
            onChangeText={setSearchQuery}
          />
        </View>
        <TouchableOpacity style={styles.iconBtn} onPress={() => setIsCalendarView(!isCalendarView)}>
          <Ionicons name={isCalendarView ? "list" : "calendar"} size={24} color="#333" />
        </TouchableOpacity>
      </View>

      <View style={styles.categoriesWrapper}>
        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.categories}>
          {CATEGORIES.map((cat) => (
            <TouchableOpacity
              key={cat}
              style={[styles.categoryChip, selectedCategory === cat && styles.categoryChipActive]}
              onPress={() => setSelectedCategory(cat)}
            >
              <Text style={[styles.categoryText, selectedCategory === cat && styles.categoryTextActive]}>{cat}</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>

      {isCalendarView ? (
        <View style={styles.calendarPlaceholder}>
          <Ionicons name="calendar" size={64} color="#ccc" />
          <Text style={styles.calendarText}>Calendar View Active</Text>
          <Text style={styles.calendarSubText}>Select a date to see events</Text>
        </View>
      ) : (
        <FlatList
          data={filteredEvents}
          keyExtractor={(item) => item.id}
          renderItem={renderEventCard}
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
        />
      )}

      <TouchableOpacity style={styles.fab} onPress={() => setIsCreateModalOpen(true)}>
        <Ionicons name="add" size={30} color="#fff" />
      </TouchableOpacity>

      <Modal visible={isCreateModalOpen} animationType="slide" transparent>
        <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'} style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Create Event</Text>
              <TouchableOpacity onPress={() => setIsCreateModalOpen(false)}>
                <Ionicons name="close" size={24} color="#333" />
              </TouchableOpacity>
            </View>
            <TextInput style={styles.input} placeholder="Event Title" />
            <TextInput style={styles.input} placeholder="Date & Time" />
            <TextInput style={styles.input} placeholder="Location" />
            <TextInput style={styles.input} placeholder="Category" />
            <TouchableOpacity style={styles.saveBtn} onPress={() => setIsCreateModalOpen(false)}>
              <Text style={styles.saveBtnText}>Create</Text>
            </TouchableOpacity>
          </View>
        </KeyboardAvoidingView>
      </Modal>
    </SafeAreaView>
  );
}

