import { NextRequest, NextResponse } from "next/server";
import { Prisma } from "@prisma/client";
import { z } from "zod";
import { getServerSession } from "next-auth";

import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const MAX_RETRIES = 3;

const transferSchema = z
  .object({
    recipientWalletId: z.string().uuid().optional(),
    recipientUserId: z.string().uuid().optional(),
    currency: z
      .string()
      .trim()
      .length(3)
      .transform((value) => value.toUpperCase()),
    amount: z
      .union([z.string(), z.number()])
      .transform((value) => String(value).trim())
      .refine((value) => /^\d+(\.\d{1,2})?$/.test(value), "Amount must be a positive decimal with up to 2 places")
      .transform((value) => new Prisma.Decimal(value))
      .refine((value) => value.gt(0), "Amount must be greater than zero")
      .refine((value) => value.lte(new Prisma.Decimal("1000000")), "Amount exceeds transfer limit"),
    idempotencyKey: z.string().trim().min(8).max(128).optional(),
    memo: z.string().trim().max(280).optional(),
  })
  .refine((data) => data.recipientWalletId || data.recipientUserId, {
    message: "recipientWalletId or recipientUserId is required",
    path: ["recipientWalletId"],
  });

class ApiError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
  ) {
    super(message);
  }
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

function json(status: number, body: Record<string, unknown>) {
  return NextResponse.json(body, { status });
}

function isRetryable(error: unknown) {
  if (error instanceof Prisma.PrismaClientKnownRequestError) {
    return ["P2034", "P2028", "P1008", "P1017"].includes(error.code);
  }

  const message = error instanceof Error ? error.message.toLowerCase() : "";
  return (
    message.includes("deadlock") ||
    message.includes("serialization") ||
    message.includes("write conflict") ||
    message.includes("transaction already closed")
  );
}

function serializeDecimal(value: unknown) {
  return value instanceof Prisma.Decimal ? value.toFixed(2) : String(value ?? "0.00");
}

function serializeTransfer(transfer: any, idempotent = false) {
  return {
    id: transfer.id,
    status: transfer.status,
    currency: transfer.currency,
    amount: serializeDecimal(transfer.amount),
    senderWalletId: transfer.senderWalletId,
    recipientWalletId: transfer.recipientWalletId,
    idempotencyKey: transfer.idempotencyKey,
    memo: transfer.memo,
    createdAt: transfer.createdAt,
    idempotent,
  };
}

async function withRetry<T>(operation: () => Promise<T>) {
  let lastError: unknown;

  for (let attempt = 1; attempt <= MAX_RETRIES; attempt += 1) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;

      if (error instanceof ApiError || !isRetryable(error) || attempt === MAX_RETRIES) {
        throw error;
      }

      await sleep(75 * attempt ** 2);
    }
  }

  throw lastError;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;

    if (!userId) {
      return json(401, { error: "Unauthorized" });
    }

    const rawBody = await request.json().catch(() => null);
    const parsed = transferSchema.safeParse(rawBody);

    if (!parsed.success) {
      return json(400, {
        error: "Invalid transfer request",
        issues: parsed.error.flatten().fieldErrors,
      });
    }

    const { amount, currency, recipientUserId, recipientWalletId, idempotencyKey, memo } = parsed.data;

    if (idempotencyKey) {
      const existing = await prisma.walletTransfer.findFirst({
        where: { senderUserId: userId, idempotencyKey },
      });

      if (existing) {
        return json(200, { transfer: serializeTransfer(existing, true) });
      }
    }

    const currentWallet = await prisma.wallet.findFirst({
      where: { userId, currency },
      select: { id: true, balance: true },
    });

    if (!currentWallet) {
      return json(404, { error: "Sender wallet not found" });
    }

    if (currentWallet.balance.lt(amount)) {
      return json(409, {
        error: "Insufficient funds",
        balance: serializeDecimal(currentWallet.balance),
      });
    }

    const result = await withRetry(async () =>
      prisma.$transaction(
        async (tx) => {
          const senderWallet = await tx.wallet.findFirst({
            where: { userId, currency },
            select: { id: true, userId: true, balance: true, currency: true },
          });

          if (!senderWallet) {
            throw new ApiError(404, "sender_wallet_not_found", "Sender wallet not found");
          }

          const recipientWallet = recipientWalletId
            ? await tx.wallet.findUnique({
                where: { id: recipientWalletId },
                select: { id: true, userId: true, currency: true },
              })
            : await tx.wallet.findFirst({
                where: { userId: recipientUserId, currency },
                select: { id: true, userId: true, currency: true },
              });

          if (!recipientWallet || recipientWallet.currency !== currency) {
            throw new ApiError(404, "recipient_wallet_not_found", "Recipient wallet not found");
          }

          if (recipientWallet.id === senderWallet.id) {
            throw new ApiError(400, "same_wallet_transfer", "Cannot transfer to the same wallet");
          }

          if (idempotencyKey) {
            const existing = await tx.walletTransfer.findFirst({
              where: { senderUserId: userId, idempotencyKey },
            });

            if (existing) {
              return { transfer: existing, senderBalance: senderWallet.balance, idempotent: true };
            }
          }

          const debit = await tx.wallet.updateMany({
            where: {
              id: senderWallet.id,
              balance: { gte: amount },
            },
            data: {
              balance: { decrement: amount },
            },
          });

          if (debit.count !== 1) {
            throw new ApiError(409, "insufficient_funds", "Insufficient funds");
          }

          const updatedRecipientWallet = await tx.wallet.update({
            where: { id: recipientWallet.id },
            data: { balance: { increment: amount } },
            select: { balance: true },
          });

          const updatedSenderWallet = await tx.wallet.findUniqueOrThrow({
            where: { id: senderWallet.id },
            select: { balance: true },
          });

          const transfer = await tx.walletTransfer.create({
            data: {
              senderUserId: userId,
              recipientUserId: recipientWallet.userId,
              senderWalletId: senderWallet.id,
              recipientWalletId: recipientWallet.id,
              currency,
              amount,
              status: "COMPLETED",
              idempotencyKey,
              memo,
            },
          });

          await tx.walletTransaction.createMany({
            data: [
              {
                walletId: senderWallet.id,
                transferId: transfer.id,
                type: "DEBIT",
                amount: amount.neg(),
                balanceAfter: updatedSenderWallet.balance,
                currency,
                description: memo ?? "Wallet transfer",
              },
              {
                walletId: recipientWallet.id,
                transferId: transfer.id,
                type: "CREDIT",
                amount,
                balanceAfter: updatedRecipientWallet.balance,
                currency,
                description: memo ?? "Wallet transfer",
              },
            ],
          });

          return {
            transfer,
            senderBalance: updatedSenderWallet.balance,
            idempotent: false,
          };
        },
        {
          isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
          maxWait: 5_000,
          timeout: 10_000,
        },
      ),
    );

    return json(result.idempotent ? 200 : 201, {
      transfer: serializeTransfer(result.transfer, result.idempotent),
      balance: serializeDecimal(result.senderBalance),
    });
  } catch (error) {
    if (error instanceof ApiError) {
      return json(error.status, { error: error.message, code: error.code });
    }

    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2002") {
      return json(409, { error: "Duplicate transfer request", code: "duplicate_transfer" });
    }

    console.error("wallet transfer failed", error);
    return json(500, { error: "Unable to complete transfer" });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

const TransferSchema = z.object({
  fromWalletId: z.string().uuid(),
  toWalletId: z.string().uuid(),
  amount: z.number().positive().multipleOf(0.01),
  currency: z.string().length(3).toUpperCase(),
  idempotencyKey: z.string().min(1).max(128).optional(),
  note: z.string().max(256).optional(),
});

type TransferPayload = z.infer<typeof TransferSchema>;

interface Wallet {
  id: string;
  ownerId: string;
  balance: number;
  currency: string;
  locked: boolean;
}

interface Transaction {
  id: string;
  fromWalletId: string;
  toWalletId: string;
  amount: number;
  currency: string;
  status: "pending" | "completed" | "failed";
  createdAt: string;
  note?: string;
}

const wallets = new Map<string, Wallet>([
  [
    "11111111-1111-1111-1111-111111111111",
    { id: "11111111-1111-1111-1111-111111111111", ownerId: "user-a", balance: 5000, currency: "USD", locked: false },
  ],
  [
    "22222222-2222-2222-2222-222222222222",
    { id: "22222222-2222-2222-2222-222222222222", ownerId: "user-b", balance: 1000, currency: "USD", locked: false },
  ],
]);

const transactions = new Map<string, Transaction>();
const idempotencyCache = new Map<string, Transaction>();

function generateId(): string {
  return crypto.randomUUID();
}

async function getWallet(id: string): Promise<Wallet | null> {
  return wallets.get(id) ?? null;
}

async function executeTransfer(
  payload: TransferPayload,
  attempt: number
): Promise<Transaction> {
  const from = await getWallet(payload.fromWalletId);
  const to = await getWallet(payload.toWalletId);

  if (!from) throw Object.assign(new Error("Source wallet not found"), { code: "WALLET_NOT_FOUND", status: 404 });
  if (!to) throw Object.assign(new Error("Destination wallet not found"), { code: "WALLET_NOT_FOUND", status: 404 });
  if (from.locked) throw Object.assign(new Error("Source wallet is locked"), { code: "WALLET_LOCKED", status: 422 });
  if (to.locked) throw Object.assign(new Error("Destination wallet is locked"), { code: "WALLET_LOCKED", status: 422 });
  if (from.currency !== payload.currency || to.currency !== payload.currency) {
    throw Object.assign(new Error("Currency mismatch"), { code: "CURRENCY_MISMATCH", status: 422 });
  }
  if (from.balance < payload.amount) {
    throw Object.assign(new Error("Insufficient funds"), { code: "INSUFFICIENT_FUNDS", status: 422 });
  }
  if (from.id === to.id) {
    throw Object.assign(new Error("Cannot transfer to the same wallet"), { code: "SAME_WALLET", status: 422 });
  }

  if (attempt > 1) {
    await new Promise((r) => setTimeout(r, 50 * attempt));
  }

  from.balance = parseFloat((from.balance - payload.amount).toFixed(2));
  to.balance = parseFloat((to.balance + payload.amount).toFixed(2));

  const tx: Transaction = {
    id: generateId(),
    fromWalletId: payload.fromWalletId,
    toWalletId: payload.toWalletId,
    amount: payload.amount,
    currency: payload.currency,
    status: "completed",
    createdAt: new Date().toISOString(),
    note: payload.note,
  };

  transactions.set(tx.id, tx);
  return tx;
}

async function withRetry<T>(
  fn: (attempt: number) => Promise<T>,
  maxAttempts = 3,
  retryableCodes = new Set(["TRANSIENT_ERROR"])
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn(attempt);
    } catch (err: unknown) {
      lastError = err;
      const code = (err as { code?: string }).code;
      if (!code || !retryableCodes.has(code)) throw err;
      if (attempt === maxAttempts) throw err;
    }
  }
  throw lastError;
}

function errorResponse(message: string, code: string, status: number, details?: unknown) {
  return NextResponse.json({ error: { message, code, details } }, { status });
}

export async function POST(req: NextRequest) {
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return errorResponse("Invalid JSON body", "INVALID_BODY", 400);
  }

  const parsed = TransferSchema.safeParse(body);
  if (!parsed.success) {
    return errorResponse("Validation failed", "VALIDATION_ERROR", 400, parsed.error.flatten());
  }

  const payload = parsed.data;

  if (payload.idempotencyKey) {
    const cached = idempotencyCache.get(payload.idempotencyKey);
    if (cached) {
      return NextResponse.json({ data: cached, idempotent: true }, { status: 200 });
    }
  }

  let transaction: Transaction;
  try {
    transaction = await withRetry((attempt) => executeTransfer(payload, attempt), 3);
  } catch (err: unknown) {
    const e = err as { message?: string; code?: string; status?: number };
    const status = e.status ?? 500;
    const code = e.code ?? "INTERNAL_ERROR";
    const message = e.message ?? "An unexpected error occurred";
    return errorResponse(message, code, status);
  }

  if (payload.idempotencyKey) {
    idempotencyCache.set(payload.idempotencyKey, transaction);
  }

  return NextResponse.json({ data: transaction }, { status: 201 });
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const walletId = searchParams.get("walletId");

  if (!walletId) {
    return errorResponse("walletId query parameter is required", "MISSING_PARAM", 400);
  }

  const wallet = await getWallet(walletId);
  if (!wallet) {
    return errorResponse("Wallet not found", "WALLET_NOT_FOUND", 404);
  }

  const history = Array.from(transactions.values()).filter(
    (tx) => tx.fromWalletId === walletId || tx.toWalletId === walletId
  );

  return NextResponse.json({
    data: {
      wallet: { id: wallet.id, balance: wallet.balance, currency: wallet.currency },
      transactions: history.sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
    },
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { db } from '@/lib/db';

const transferSchema = z.object({
  senderId: z.string().uuid('Invalid sender ID format'),
  receiverId: z.string().uuid('Invalid receiver ID format'),
  amount: z.number().positive('Amount must be greater than zero').multipleOf(0.01, 'Amount cannot have more than 2 decimal places'),
  currency: z.string().length(3).default('USD'),
  description: z.string().max(255).optional(),
});

type TransferRequest = z.infer<typeof transferSchema>;

async function withRetry<T>(
  operation: () => Promise<T>,
  maxRetries: number = 3,
  baseDelayMs: number = 100
): Promise<T> {
  let attempt = 0;
  while (attempt < maxRetries) {
    try {
      return await operation();
    } catch (error: any) {
      attempt++;
      const isRetryable = error.code === 'P2034' || error.message.includes('deadlock') || error.message.includes('conflict');

      if (!isRetryable || attempt >= maxRetries) {
        throw error;
      }

      const delay = baseDelayMs * Math.pow(2, attempt - 1) + Math.random() * 50;
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw new Error('Max retries exceeded');
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => null);

    if (!body) {
      return NextResponse.json({ error: 'Invalid JSON payload' }, { status: 400 });
    }

    const validationResult = transferSchema.safeParse(body);

    if (!validationResult.success) {
      return NextResponse.json({ 
        error: 'Validation failed', 
        details: validationResult.error.flatten().fieldErrors 
      }, { status: 400 });
    }

    const { senderId, receiverId, amount, currency, description } = validationResult.data;

    if (senderId === receiverId) {
      return NextResponse.json({ error: 'Sender and receiver cannot be the same' }, { status: 400 });
    }

    const transactionResult = await withRetry(async () => {
      return await db.$transaction(async (tx) => {
        const senderWallet = await tx.wallet.findUnique({
          where: { userId: senderId },
          select: { id: true, balance: true, currency: true }
        });

        if (!senderWallet) {
          throw new Error('SENDER_NOT_FOUND');
        }

        if (senderWallet.currency !== currency) {
          throw new Error('CURRENCY_MISMATCH');
        }

        if (senderWallet.balance < amount) {
          throw new Error('INSUFFICIENT_FUNDS');
        }

        const receiverWallet = await tx.wallet.findUnique({
          where: { userId: receiverId },
          select: { id: true, currency: true }
        });

        if (!receiverWallet) {
          throw new Error('RECEIVER_NOT_FOUND');
        }

        if (receiverWallet.currency !== currency) {
          throw new Error('CURRENCY_MISMATCH');
        }

        await tx.wallet.update({
          where: { id: senderWallet.id },
          data: { balance: { decrement: amount } },
        });

        await tx.wallet.update({
          where: { id: receiverWallet.id },
          data: { balance: { increment: amount } },
        });

        const transferRecord = await tx.transaction.create({
          data: {
            senderId,
            receiverId,
            amount,
            currency,
            type: 'TRANSFER',
            status: 'COMPLETED',
            description: description || 'Internal wallet transfer',
          },
        });

        return transferRecord;
      }, {
        isolationLevel: 'Serializable',
        maxWait: 5000,
        timeout: 10000,
      });
    });

    return NextResponse.json({
      success: true,
      message: 'Transfer completed successfully',
      data: {
        transactionId: transactionResult.id,
        amount: transactionResult.amount,
        currency: transactionResult.currency,
        timestamp: transactionResult.createdAt
      }
    }, { status: 200 });

  } catch (error: any) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';

    switch (errorMessage) {
      case 'SENDER_NOT_FOUND':
        return NextResponse.json({ error: 'Sender wallet not found' }, { status: 404 });
      case 'RECEIVER_NOT_FOUND':
        return NextResponse.json({ error: 'Receiver wallet not found' }, { status: 404 });
      case 'INSUFFICIENT_FUNDS':
        return NextResponse.json({ error: 'Insufficient funds for transfer' }, { status: 400 });
      case 'CURRENCY_MISMATCH':
        return NextResponse.json({ error: 'Wallet currencies do not match the requested transfer currency' }, { status: 400 });
      default:
        console.error('[WALLET_TRANSFER_ERROR]', error);
        return NextResponse.json({ error: 'An internal server error occurred while processing the transfer' }, { status: 500 });
    }
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

type ReportUser = {
  id?: string;
  role?: string;
  agentId?: string;
  agencyId?: string;
};

type QuoteRow = {
  id: string;
  createdAt: Date;
  status?: string | null;
  premium?: unknown;
  carrier?: string | null;
  productType?: string | null;
  state?: string | null;
  agentId?: string | null;
  agencyId?: string | null;
  agent?: { id: string; name?: string | null; email?: string | null } | null;
  policy?: {
    id: string;
    status?: string | null;
    premium?: unknown;
    boundAt?: Date | null;
    effectiveDate?: Date | null;
  } | null;
};

type Accumulator = {
  group: string;
  quoteCount: number;
  submittedCount: number;
  boundCount: number;
  lostCount: number;
  quotedPremium: number;
  boundPremium: number;
};

const REPORT_ROLES = new Set(["ADMIN", "MANAGER", "ANALYST", "AGENT"]);
const BOUND_STATUSES = new Set(["BOUND", "ISSUED", "ACTIVE", "IN_FORCE"]);
const SUBMITTED_STATUSES = new Set(["SUBMITTED", "BOUND", "ISSUED", "ACTIVE", "IN_FORCE"]);
const LOST_STATUSES = new Set(["DECLINED", "REJECTED", "LOST", "EXPIRED", "CANCELLED"]);
const GROUPS = new Set(["day", "month", "carrier", "product", "state", "agent"]);

export async function GET(req: NextRequest) {
  let userId: string | undefined;

  try {
    const session = await getServerSession(authOptions);
    const user = session?.user as ReportUser | undefined;
    userId = user?.id;

    const role = String(user?.role ?? "").toUpperCase();
    if (!user || !REPORT_ROLES.has(role)) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const { searchParams } = req.nextUrl;
    const now = new Date();
    const defaultFrom = new Date(now);
    defaultFrom.setDate(defaultFrom.getDate() - 30);

    const from = parseDate(searchParams.get("from") ?? searchParams.get("dateFrom"), defaultFrom, false);
    const to = parseDate(searchParams.get("to") ?? searchParams.get("dateTo"), now, true);

    if (Number.isNaN(from.getTime()) || Number.isNaN(to.getTime()) || from > to) {
      return NextResponse.json({ error: "Invalid date range" }, { status: 400 });
    }

    const groupBy = GROUPS.has(searchParams.get("groupBy") ?? "")
      ? String(searchParams.get("groupBy"))
      : "carrier";
    const format = String(searchParams.get("format") ?? "").toLowerCase();
    const limit = Math.min(Math.max(Number(searchParams.get("limit") ?? 25000), 1), 50000);
    const requestedAgentId = searchParams.get("agentId") || undefined;

    const where: Record<string, unknown> = {
      createdAt: { gte: from, lte: to },
    };

    applyListFilter(where, "carrier", listParam(searchParams, "carrier"));
    applyListFilter(where, "productType", listParam(searchParams, "productType", "product"));
    applyListFilter(where, "state", listParam(searchParams, "state"));
    applyListFilter(where, "status", listParam(searchParams, "status"));

    if (role === "AGENT") {
      const ownAgentId = user.agentId ?? user.id;
      if (requestedAgentId && requestedAgentId !== ownAgentId) {
        return NextResponse.json({ error: "Cannot access another agent's report" }, { status: 403 });
      }
      where.agentId = ownAgentId;
    } else if (requestedAgentId) {
      where.agentId = requestedAgentId;
    }

    if (role === "MANAGER") {
      if (!user.agencyId) {
        return NextResponse.json({ error: "Manager is not assigned to an agency" }, { status: 403 });
      }
      where.agencyId = user.agencyId;
    }

    const quotes = (await prisma.quote.findMany({
      where,
      take: limit,
      orderBy: { createdAt: "asc" },
      select: {
        id: true,
        createdAt: true,
        status: true,
        premium: true,
        carrier: true,
        productType: true,
        state: true,
        agentId: true,
        agencyId: true,
        agent: { select: { id: true, name: true, email: true } },
        policy: {
          select: {
            id: true,
            status: true,
            premium: true,
            boundAt: true,
            effectiveDate: true,
          },
        },
      },
    })) as QuoteRow[];

    const groups = new Map<string, Accumulator>();
    const totals = newAccumulator("Total");

    for (const quote of quotes) {
      const key = groupKey(quote, groupBy);
      const bucket = groups.get(key) ?? newAccumulator(key);
      addQuote(bucket, quote);
      addQuote(totals, quote);
      groups.set(key, bucket);
    }

    const rows = [...groups.values()].map(finalize).sort((a, b) => a.group.localeCompare(b.group));
    const payload = {
      generatedAt: new Date().toISOString(),
      filters: {
        from: from.toISOString(),
        to: to.toISOString(),
        groupBy,
        carrier: listParam(searchParams, "carrier"),
        productType: listParam(searchParams, "productType", "product"),
        state: listParam(searchParams, "state"),
        status: listParam(searchParams, "status"),
        agentId: where.agentId ?? null,
      },
      truncated: quotes.length === limit,
      totals: finalize(totals),
      rows,
    };

    if (format === "csv") {
      return new NextResponse(toCsv([payload.totals, ...rows]), {
        status: 200,
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="insurance-report-${from.toISOString().slice(0, 10)}-${to
            .toISOString()
            .slice(0, 10)}.csv"`,
        },
      });
    }

    return NextResponse.json(payload);
  } catch (error) {
    logger.error(
      {
        err:
          error instanceof Error
            ? { message: error.message, stack: error.stack, name: error.name }
            : error,
        userId,
        route: "app/api/reports",
      },
      "Failed to generate insurance report",
    );

    return NextResponse.json({ error: "Unable to generate report" }, { status: 500 });
  }
}

function parseDate(value: string | null, fallback: Date, endOfDay: boolean) {
  if (!value) return fallback;
  const date = new Date(value);
  if (!Number.isNaN(date.getTime()) && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
    date.setHours(endOfDay ? 23 : 0, endOfDay ? 59 : 0, endOfDay ? 59 : 0, endOfDay ? 999 : 0);
  }
  return date;
}

function listParam(params: URLSearchParams, ...names: string[]) {
  for (const name of names) {
    const raw = params.get(name);
    if (raw) return raw.split(",").map((v) => v.trim()).filter(Boolean);
  }
  return [];
}

function applyListFilter(where: Record<string, unknown>, field: string, values: string[]) {
  if (values.length === 1) where[field] = values[0];
  if (values.length > 1) where[field] = { in: values };
}

function newAccumulator(group: string): Accumulator {
  return {
    group,
    quoteCount: 0,
    submittedCount: 0,
    boundCount: 0,
    lostCount: 0,
    quotedPremium: 0,
    boundPremium: 0,
  };
}

function addQuote(acc: Accumulator, quote: QuoteRow) {
  const status = String(quote.status ?? "").toUpperCase();
  const policyStatus = String(quote.policy?.status ?? "").toUpperCase();
  const bound = BOUND_STATUSES.has(status) || BOUND_STATUSES.has(policyStatus) || Boolean(quote.policy?.boundAt);
  const submitted = bound || SUBMITTED_STATUSES.has(status);
  const lost = LOST_STATUSES.has(status) || LOST_STATUSES.has(policyStatus);

  acc.quoteCount += 1;
  acc.submittedCount += submitted ? 1 : 0;
  acc.boundCount += bound ? 1 : 0;
  acc.lostCount += lost ? 1 : 0;
  acc.quotedPremium += money(quote.premium);
  acc.boundPremium += bound ? money(quote.policy?.premium ?? quote.premium) : 0;
}

function finalize(acc: Accumulator) {
  return {
    group: acc.group,
    quoteCount: acc.quoteCount,
    submittedCount: acc.submittedCount,
    boundCount: acc.boundCount,
    lostCount: acc.lostCount,
    quotedPremium: round(acc.quotedPremium),
    boundPremium: round(acc.boundPremium),
    averageQuotedPremium: acc.quoteCount ? round(acc.quotedPremium / acc.quoteCount) : 0,
    averageBoundPremium: acc.boundCount ? round(acc.boundPremium / acc.boundCount) : 0,
    quoteToBindConversionRate: rate(acc.boundCount, acc.quoteCount),
    submittedToBindConversionRate: rate(acc.boundCount, acc.submittedCount),
  };
}

function groupKey(quote: QuoteRow, groupBy: string) {
  if (groupBy === "day") return quote.createdAt.toISOString().slice(0, 10);
  if (groupBy === "month") return quote.createdAt.toISOString().slice(0, 7);
  if (groupBy === "product") return quote.productType || "Unspecified";
  if (groupBy === "state") return quote.state || "Unspecified";
  if (groupBy === "agent") return quote.agent?.name || quote.agent?.email || quote.agentId || "Unassigned";
  return quote.carrier || "Unspecified";
}

function money(value: unknown) {
  if (value == null) return 0;
  if (typeof value === "number") return value;
  if (typeof value === "string") return Number(value) || 0;
  if (typeof value === "object" && "toNumber" in value && typeof value.toNumber === "function") {
    return value.toNumber();
  }
  return Number(value) || 0;
}

function rate(numerator: number, denominator: number) {
  return denominator ? round((numerator / denominator) * 100) : 0;
}

function round(value: number) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function toCsv(rows: ReturnType<typeof finalize>[]) {
  const headers = [
    "group",
    "quoteCount",
    "submittedCount",
    "boundCount",
    "lostCount",
    "quotedPremium",
    "boundPremium",
    "averageQuotedPremium",
    "averageBoundPremium",
    "quoteToBindConversionRate",
    "submittedToBindConversionRate",
  ];

  return [
    headers.join(","),
    ...rows.map((row) => headers.map((key) => csvValue(row[key as keyof typeof row])).join(",")),
  ].join("\n");
}

function csvValue(value: unknown) {
  const text = String(value ?? "");
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { db } from "@/lib/db";
import { z } from "zod";

const ALLOWED_ROLES = ["admin", "manager", "analyst"];

const filtersSchema = z.object({
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  agentId: z.string().optional(),
  productType: z.enum(["auto", "home", "life", "health", "all"]).default("all"),
  region: z.string().optional(),
  format: z.enum(["json", "csv"]).default("json"),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(500).default(50),
});

type ReportRow = {
  agentId: string;
  agentName: string;
  productType: string;
  region: string;
  leadsCount: number;
  quotesCount: number;
  policiesIssued: number;
  premiumTotal: number;
  conversionRate: number;
  period: string;
};

function toCSV(rows: ReportRow[]): string {
  const headers = [
    "Agent ID",
    "Agent Name",
    "Product Type",
    "Region",
    "Leads",
    "Quotes",
    "Policies Issued",
    "Premium Total",
    "Conversion Rate (%)",
    "Period",
  ];
  const escape = (v: string | number) =>
    typeof v === "string" && v.includes(",") ? `"${v}"` : String(v);

  const lines = [
    headers.join(","),
    ...rows.map((r) =>
      [
        r.agentId,
        r.agentName,
        r.productType,
        r.region,
        r.leadsCount,
        r.quotesCount,
        r.policiesIssued,
        r.premiumTotal.toFixed(2),
        r.conversionRate.toFixed(2),
        r.period,
      ]
        .map(escape)
        .join(",")
    ),
  ];
  return lines.join("\n");
}

function buildWhereClause(filters: z.infer<typeof filtersSchema>) {
  const conditions: string[] = [];
  const params: unknown[] = [];

  if (filters.startDate) {
    params.push(new Date(filters.startDate));
    conditions.push(`r.created_at >= $${params.length}`);
  }
  if (filters.endDate) {
    params.push(new Date(filters.endDate));
    conditions.push(`r.created_at <= $${params.length}`);
  }
  if (filters.agentId) {
    params.push(filters.agentId);
    conditions.push(`r.agent_id = $${params.length}`);
  }
  if (filters.productType !== "all") {
    params.push(filters.productType);
    conditions.push(`r.product_type = $${params.length}`);
  }
  if (filters.region) {
    params.push(filters.region);
    conditions.push(`r.region = $${params.length}`);
  }

  return {
    where: conditions.length ? `WHERE ${conditions.join(" AND ")}` : "",
    params,
  };
}

async function fetchReportData(
  filters: z.infer<typeof filtersSchema>
): Promise<{ rows: ReportRow[]; total: number }> {
  const { where, params } = buildWhereClause(filters);
  const offset = (filters.page - 1) * filters.pageSize;

  const countParams = [...params];
  const dataParams = [...params, filters.pageSize, offset];

  const countResult = await db.query<{ count: string }>(
    `SELECT COUNT(*) AS count
     FROM insurance_reports r
     ${where}`,
    countParams
  );

  const total = parseInt(countResult.rows[0]?.count ?? "0", 10);

  const result = await db.query<{
    agent_id: string;
    agent_name: string;
    product_type: string;
    region: string;
    leads_count: string;
    quotes_count: string;
    policies_issued: string;
    premium_total: string;
    period: string;
  }>(
    `SELECT
       r.agent_id,
       a.full_name AS agent_name,
       r.product_type,
       r.region,
       SUM(r.leads_count)::int AS leads_count,
       SUM(r.quotes_count)::int AS quotes_count,
       SUM(r.policies_issued)::int AS policies_issued,
       SUM(r.premium_total)::numeric AS premium_total,
       TO_CHAR(DATE_TRUNC('month', r.created_at), 'YYYY-MM') AS period
     FROM insurance_reports r
     JOIN agents a ON a.id = r.agent_id
     ${where}
     GROUP BY r.agent_id, a.full_name, r.product_type, r.region, period
     ORDER BY period DESC, r.agent_id
     LIMIT $${dataParams.length - 1} OFFSET $${dataParams.length}`,
    dataParams
  );

  const rows: ReportRow[] = result.rows.map((r) => {
    const leads = parseInt(r.leads_count, 10) || 0;
    const policies = parseInt(r.policies_issued, 10) || 0;
    return {
      agentId: r.agent_id,
      agentName: r.agent_name,
      productType: r.product_type,
      region: r.region,
      leadsCount: leads,
      quotesCount: parseInt(r.quotes_count, 10) || 0,
      policiesIssued: policies,
      premiumTotal: parseFloat(r.premium_total) || 0,
      conversionRate: leads > 0 ? (policies / leads) * 100 : 0,
      period: r.period,
    };
  });

  return { rows, total };
}

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const userRole = (session.user as { role?: string }).role ?? "";
    if (!ALLOWED_ROLES.includes(userRole)) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const parsed = filtersSchema.safeParse(
      Object.fromEntries(req.nextUrl.searchParams)
    );

    if (!parsed.success) {
      return NextResponse.json(
        { error: "Invalid query parameters", details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    const filters = parsed.data;

    if (userRole === "analyst" && filters.agentId !== session.user.id) {
      filters.agentId = session.user.id as string;
    }

    const { rows, total } = await fetchReportData(filters);

    if (filters.format === "csv") {
      const csv = toCSV(rows);
      return new NextResponse(csv, {
        status: 200,
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": `attachment; filename="insurance-report-${Date.now()}.csv"`,
        },
      });
    }

    return NextResponse.json({
      data: rows,
      meta: {
        total,
        page: filters.page,
        pageSize: filters.pageSize,
        totalPages: Math.ceil(total / filters.pageSize),
      },
    });
  } catch (err) {
    console.error("[reports/route] Unhandled error:", err);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import prisma from '@/lib/prisma';
import { logger } from '@/lib/logger';

const ALLOWED_ROLES = ['ADMIN', 'MANAGER', 'DIRECTOR'];

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    if (!ALLOWED_ROLES.includes(session.user.role)) {
      logger.warn(`Access denied for user ${session.user.id} with role ${session.user.role}`);
      return NextResponse.json({ error: 'Forbidden: Insufficient permissions' }, { status: 403 });
    }

    const { searchParams } = new URL(req.url);
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');
    const status = searchParams.get('status');
    const agentId = searchParams.get('agentId');
    const format = searchParams.get('format') || 'json';

    const whereClause: any = {};

    if (startDate || endDate) {
      whereClause.createdAt = {};
      if (startDate) whereClause.createdAt.gte = new Date(startDate);
      if (endDate) whereClause.createdAt.lte = new Date(endDate);
    }

    if (status) {
      whereClause.status = status;
    }

    if (agentId && session.user.role !== 'MANAGER') {
      whereClause.agentId = agentId;
    } else if (session.user.role === 'MANAGER') {
      whereClause.agencyId = session.user.agencyId;
      if (agentId) whereClause.agentId = agentId;
    }

    const applications = await prisma.insuranceApplication.findMany({
      where: whereClause,
      include: {
        agent: { select: { firstName: true, lastName: true } },
        product: { select: { name: true, category: true } }
      },
      orderBy: { createdAt: 'desc' }
    });

    const totalApplications = applications.length;
    const approvedApplications = applications.filter(app => app.status === 'APPROVED');
    const totalApproved = approvedApplications.length;

    const conversionRate = totalApplications > 0 
      ? ((totalApproved / totalApplications) * 100).toFixed(2) 
      : '0.00';

    const totalPremiumVolume = approvedApplications.reduce(
      (sum, app) => sum + (app.premiumAmount || 0), 
      0
    );

    const aggregationMetrics = {
      totalApplications,
      totalApproved,
      conversionRate: `${conversionRate}%`,
      totalPremiumVolume,
      period: { startDate, endDate }
    };

    if (format.toLowerCase() === 'csv') {
      const csvContent = generateCSV(applications, aggregationMetrics);

      return new NextResponse(csvContent, {
        status: 200,
        headers: {
          'Content-Type': 'text/csv',
          'Content-Disposition': `attachment; filename="insurance_report_${new Date().toISOString().split('T')[0]}.csv"`,
        },
      });
    }

    return NextResponse.json({
      metrics: aggregationMetrics,
      data: applications
    }, { status: 200 });

  } catch (error) {
    logger.error('Error generating insurance report:', error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

function generateCSV(applications: any[], metrics: any): string {
  const escapeCSV = (val: any) => {
    if (val === null || val === undefined) return '""';
    const str = String(val);
    if (str.includes(',') || str.includes('"') || str.includes('\n')) {
      return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
  };

  const headers = [
    'Application ID',
    'Created At',
    'Agent Name',
    'Product Category',
    'Product Name',
    'Status',
    'Premium Amount'
  ];

  const rows = applications.map(app => [
    escapeCSV(app.id),
    escapeCSV(app.createdAt.toISOString()),
    escapeCSV(`${app.agent?.firstName || ''} ${app.agent?.lastName || ''}`.trim()),
    escapeCSV(app.product?.category),
    escapeCSV(app.product?.name),
    escapeCSV(app.status),
    escapeCSV(app.premiumAmount || 0)
  ].join(','));

  const summaryHeaders = ['Total Applications', 'Total Approved', 'Conversion Rate', 'Total Premium Volume'];
  const summaryRow = [
    escapeCSV(metrics.totalApplications),
    escapeCSV(metrics.totalApproved),
    escapeCSV(metrics.conversionRate),
    escapeCSV(metrics.totalPremiumVolume)
  ].join(',');

  return [
    '--- SUMMARY ---',
    summaryHeaders.join(','),
    summaryRow,
    '',
    '--- DETAILS ---',
    headers.join(','),
    ...rows
  ].join('\n');
}
